local config = {
  ui_story_2001_1_X1_dialog_content = "<color=#e8d9bb>Tierra estéril en la Lumopolis rural</color>",
  ui_story_2001_1_X2_dialog_content = "<color=#e8d9bb>Un enjambre de vehículos corría frenéticamente en nubes de polvo, con el radio y el ruido del motor retumbando con fuerza de lejos a cerca, hasta que las brillantes banderas de Rediesel ondearon en el horizonte.</color>",
  ui_story_2001_1_1_dialog_content = "¡Ja ja, seguro logramos mucho hoy! ¡Es hora de que tengamos uno gordo como la caravana Lumopolis, también!",
  ui_story_2001_1_2_dialog_content = "Todo lo que queda es celebrar... ¡Woo!",
  ui_story_2001_1_3_dialog_content = "¿Soy yo, o la ciudad sobre nosotros se está haciendo más grande...?",
  ui_story_2001_1_4_dialog_content = "¿Estás seguro que no estamos en la dirección equivocada, Brock?",
  ui_story_2001_1_5_dialog_content = "¿Ah? ¿Qué rayos dices? ¡Tengo mis ojos pegados al mapa!",
  ui_story_2001_1_6_dialog_content = "Mira, ¿no dice “3 millas al norte de las ruinas” aquí? Mmm... Cuál es el nombre de las ruinas...",
  ui_story_2001_1_7_dialog_content = "Em, Brock... Alguna posibilidad que... Ejem... Tú sabes...",
  ui_story_2001_1_8_dialog_content = "<size=45>¿Qué hayas leído el mapa al revés?</size>",
  ui_story_2001_1_9_dialog_content = "<size=45>¿Quééé? ¡¿Rayos, quién tuvo la idea de hacer un mapa que nadie pueda leer?!</size>",
  ui_story_2001_1_10_dialog_content = "¡¿Por qué estoy corriendo en la mitad de la nada con un pedazo de papel inútil?!",
  ui_story_2001_1_11_dialog_content = "¿Em, porque pisaste y rompiste el faro de Tornillos Sueltos cuando estabas peleando?",
  ui_story_2001_1_12_dialog_content = "¡Cállate, nadie te preguntó! ¡Aun así, deberían hacerlo más duradero!",
  ui_story_2001_1_13_dialog_content = "¡Whoa! ¡Destructor, por ahí! ¡Alguien se acerca!",
  ui_story_2001_1_14_dialog_content = "¡Por favor cooperen y paren sus vehículos para inspección por Lumopolis! ¡Repito, por favor paren sus vehículos!",
  ui_story_2001_1_15_dialog_content = "¡Es la <color=#FFB400>Patrulla</color> de Lumopolis! Seguro son rápidos, y malas noticias, hay muchos de ellos...",
  ui_story_2001_1_16_dialog_content = "¡Hmph! ¡Justo a tiempo para desquitarme con esos perdedores!",
  ui_story_2001_1_17_dialog_content = "¡Alto, eso es...! Criminales buscados entre los sospechosos, solicitando refuerzos...",
  ui_story_2001_1_18_dialog_content = "Dios, solo un golpe lo sacó... ¡Todos, estén alerta, rodeen al objetivo!",
  ui_story_2001_2_1_dialog_content = "¿Qué? ¿Eso es todo? ¡Puedo atraparlos a todos yo solo!",
  ui_story_2001_2_2_dialog_content = "Qué decepcionante. ¿No tienen muchachos más fuertes?",
  ui_story_2001_2_3_dialog_content = "¡B-Brock!",
  ui_story_2001_2_4_dialog_content = "¡Qué! ¿Oye, que hay con tus heridas?",
  ui_story_2001_2_5_dialog_content = "Fueron los chicos de Lumopolis... Nos atacaron desde otra dirección y detuvieron nuestras cosas. Su líder...*tose*... Mejor ten cuidado...",
  ui_story_2001_2_6_dialog_content = "Entendido. ¡Shh, cállate, estás herido!",
  ui_story_2001_2_7_dialog_content = "¡¿Quién se atreve a saquear Rediesel Wrench?! ¡Esto me convertiría en el hazmerreír! ¡Nop, tenemos que recuperar lo nuestro!",
  ui_story_2001_2_8_dialog_content = "Todos los que aún se pueden mover, cúbranme. ¡Estoy sacando el nuevo coso tecnológico para nosotros!",
  ui_story_2001_2_9_dialog_content = "<color=#e8d9bb>Varios rayos golpearon el área frente a Brock, creando explosiones ensordecedoras antes de que pudiera reaccionar, cualquiera de las cuales podría haberlo frito fácilmente.</color>",
  ui_story_2001_2_10_dialog_content = "Parece que sabes una cosa o dos... Tú debes ser la líder del escuadrón de Lumopolis.",
  ui_story_2001_2_11_dialog_content = "¡¿Qué no te enseñó tu señor a no meterte con las cosas de los demás?!",
  ui_story_2001_2_12_dialog_content = "...",
  ui_story_2001_2_13_dialog_content = "<color=#e8d9bb>Brock no obtuvo respuesta, excepto por la respiración pesada debajo de la máscara de su oponente y el ruido crepitante del campo eléctrico.</color>",
  ui_story_2001_2_14_dialog_content = "¡Oye! ¡No me menosprecies!",
  ui_story_2001_2_15_dialog_content = "¡Bien! ¡Muéstrame qué tienes!",
  ui_story_2001_2_16_dialog_content = "...",
  ui_story_2001_2_17_dialog_content = "Eh, nada mal, supongo que no todos en Lumopolis son basura.",
  ui_story_2001_2_18_dialog_content = "¡Cómo te metiste con mis amigos, tendré que partirte para estar a mano!",
  ui_story_2001_2_19_dialog_content = "...",
  ui_story_2001_2_20_dialog_content = "Cargamos las cosas y a los heridos, Brock. ¡Debemos salir de aquí!",
  ui_story_2001_2_21_dialog_content = "¡Bien! Considérate con suerte que yo no...",
  ui_story_2001_2_22_dialog_content = "<color=#e8d9bb>Otro rayo pasó cerca de Brock, rozando la punta de su nariz, marcando en el suelo unos centímetros detrás de él.</color>",
  ui_story_2001_2_23_dialog_content = "<color=#e8d9bb>Brock notó varias personas vestidas idénticas apareciendo a lado de la figura enmascarada—</color>",
  ui_story_2001_2_24_dialog_content = "¡Eeek! ¡Mi error, mi error! ¡Es mi culpa que todos estén perdidos!",
  ui_story_2001_2_25_dialog_content = "¿Estás bien, pequeña <color=#FFB400>Michele</color>? ¡Déjame curarte!",
  ui_story_2001_2_26_dialog_content = "¿Qué les pasa a los excéntricos nobles de Lumopolis que envían a pelear a niñas flacas?",
  ui_story_2001_2_27_dialog_content = "¡No me interesa golpear niños, pero como ellos comenzaron, yo lo terminaré!",
  ui_story_2001_2_28_dialog_content = "¡El resto de ustedes lárguense para que no se metan en mi camino! ¡Y no se beban todo antes de que yo regrese!",
  ui_story_2001_2_29_dialog_content = "Perseguiremos a los bandidos, <color=#FFB400>Madam Carleen</color>...",
  ui_story_2001_2_30_dialog_content = "No te molestes.",
  ui_story_2001_2_31_dialog_content = "Michele, Raphaela, y el resto de la patrulla, descansen.",
  ui_story_2001_2_32_dialog_content = "Ignoren las ratas y concéntrense en la mayor amenaza.",
  ui_story_2001_2_33_dialog_content = "Ja, tienes buenos ojos. ¡Digo, después de todo, soy el segundo al mando de los Rediesel Wrench! Solo ven y toma un poco de esto... ¡Arrrgh!",
  ui_story_2001_2_34_dialog_content = "(¿Qué rayos pasó? Por qué está la tierra... ¿Estoy abajo?)",
  ui_story_2001_2_35_dialog_content = "...",
  ui_story_2001_2_36_dialog_content = "(¿Qué me hizo la mujer enmascarada? ¡No puedo moverme...!)",
  ui_story_2001_2_37_dialog_content = "Buen trabajo, Michele.",
  ui_story_2001_2_38_dialog_content = "Soy la Cap. Carleen, de los Guardianes. ¡Brock de Rediesel Wrench, estoy aquí para arrestarte!",
  ui_story_2001_3_1_dialog_content = "¿Has escuchado? Los Guardianes atraparon a otro jefe de Rediesel Wrench, incluso podría ser un segundo al mando esta vez.",
  ui_story_2001_3_2_dialog_content = "Sí, es mucho mejor que atrapar a un montón de peones inútiles.",
  ui_story_2001_3_3_dialog_content = "Espera a que acabe la celebración. Será el fin de esos perdedores...",
  ui_story_2001_3_4_dialog_content = "(¿Dónde estoy?)",
  ui_story_2001_3_5_dialog_content = "¡Ay-ay-ay! ¡Oye, supongo que estoy vivo!",
  ui_story_2001_3_6_dialog_content = "Tsk, ¿de dónde seguían sacando a esos bichos raros que podían manejar sus asuntos...? Me pregunto si esos idiotas ruidosos escaparon...",
  ui_story_2001_3_7_dialog_content = "¡Ja! ¡Y me preguntaba quién podría ser el fanfarrón perdedor!",
  ui_story_2001_3_8_dialog_content = "¿A quién llamas un fanfarrón perdedor? Puede que hoy esté un poco fuera de lugar, pero si ese tipo no me hubiera saltado por detrás... ¡¿Espera, quién habla ahí?!",
  ui_story_2001_3_9_dialog_content = "<size=40>Ha pasado un tiempo, Brock.</size>",
  ui_story_2001_3_10_dialog_content = "<color=#e8d9bb>Una mujer sale de las sombras, viendo astutamente a Brock</color>",
  ui_story_2001_3_11_dialog_content = "<color=#e8d9bb>Brock sintió un olor intenso pero familiar a pólvora y la miró con los ojos entrecerrados en la penumbra.</color>",
  ui_story_2001_3_12_dialog_content = "¿<color=#FFB400>Jona</color>? ¿Qué hacen aquí?",
  ui_story_2001_3_13_dialog_content = "¿Y, uh, dónde estamos?",
  ui_story_2001_3_14_dialog_content = "El corredor de la muerte de Lumopolis. Mmm, pero cómo llegué aquí. Ya lo olvidé...",
  ui_story_2001_3_15_dialog_content = "Probablemente estaba en alguna posada rematada en ruinas, teniendo un concurso de bebidas con alguien que no conocía bien, solo para despertarme aquí.",
  ui_story_2001_3_16_dialog_content = "Algún caza recompensas o espía Lumo seguro hizo mucho dinero conmigo.",
  ui_story_2001_3_17_dialog_content = "¡Pero honestamente, dada la cantidad de dinero que ofrecen por mi cabeza, hasta yo intentaría cobrarla si pudiera!",
  ui_story_2001_3_18_dialog_content = "<color=#e8d9bb>Jona contó su difícil situación como burlándose de otra persona, sus burlas reverberaron en las paredes de la celda.</color>",
  ui_story_2001_3_19_dialog_content = "Con razón desapareciste luego de la última misión... ¡Maldito Lumopolis, si tan solo los chicos hubiesen obtenido la información antes! ¡Ay!",
  ui_story_2001_3_20_dialog_content = "Cuidado. ¿Es una nueva herida, cierto? Se partirá de nuevo si no tienes cuidado.",
  ui_story_2001_3_21_dialog_content = "Lo que sirven aquí es aceptable, y no hay quejas de Sinsa por todo, por lo que en verdad no es tan malo.",
  ui_story_2001_3_22_dialog_content = "Pero holgazanear...no, digo, encerrada sin nada que hacer se está volviendo aburrido.",
  ui_story_2001_3_23_dialog_content = "Además, amontonar dos mandos de Rediesel Wrench en el corredor de la muerte en la misma celda es realmente sofocante. No quiero a un cabeza dura de compañero de celda.",
  ui_story_2001_3_24_dialog_content = "¿Qué has estado balbuceando aquí? ¿Y acabas de insultar casualmente...?",
  ui_story_2001_3_25_dialog_content = "De todas formas...",
  ui_story_2001_3_26_dialog_content = "<color=#e8d9bb>Jona tronó el cuello y los nudillos, y antes de que Brock reaccionara,</color>",
  ui_story_2001_3_27_dialog_content = "<size=45><color=#e8d9bb>un gran hoyo se hizo en la pared</color></size>",
  ui_story_2001_3_28_dialog_content = "¡Te sacaré, así que mantén el paso!",
  ui_story_2001_4_1_dialog_content = "¡Explosión en el Recinto de máxima seguridad, posible brecha! Personal de seguridad al área de inmediato...",
  ui_story_2001_4_2_dialog_content = "¡Urgh!",
  ui_story_2001_4_3_dialog_content = "Son cincuenta y un policías Lumo. Serán fáciles de lidiar, comparados con los molestos mecanismos de seguridad...",
  ui_story_2001_4_4_dialog_content = "<color=#e8d9bb>Brock dijo eso en voz alta a propósito mientras veía a Jona, quien parecía no prestar atención.</color>",
  ui_story_2001_4_5_dialog_content = "¿Oye, que hay de ti?",
  ui_story_2001_4_6_dialog_content = "¿Ah? ¿Es una competencia? No llevo la cuenta... Digamos que 50.",
  ui_story_2001_4_7_dialog_content = "Jona, me subestimas, ¿verdad?",
  ui_story_2001_4_8_dialog_content = "¡Yo nunca, especialmente al “segundo al mando de los Rediesel”! Tienes que estar a solo un dedo de derribar a Sinsa por el primer puesto, ¿verdad?",
  ui_story_2001_4_9_dialog_content = "¿D-de dónde sacaste eso? ¡Eso fue solo una mentira para darles tiempo de escapar a los chicos!",
  ui_story_2001_4_10_dialog_content = "Sí, como sea. Nadie se ríe de tus aspiraciones, a pesar de que estás 0-a-728 con 3 empates en su contra...",
  ui_story_2001_4_11_dialog_content = "Hmm, creo que estamos en el perímetro exterior de Lumopolis ahora.",
  ui_story_2001_4_12_dialog_content = "Oh. ¿Qué significa eso?",
  ui_story_2001_4_13_dialog_content = "Esa es una dirigible de la Patrulla Lumo. Parece que estamos en un pequeño <color=#FFB400>centro de lanzadera</color>.",
  ui_story_2001_4_14_dialog_content = "Nada mal. Me han perseguido mucho, ¡ya es hora de que dé un paseo en uno!",
  ui_story_2001_4_15_dialog_content = "Oye, espera...",
  ui_story_2001_4_16_dialog_content = "Suspira... ¿Por qué tenemos que ser los que lo encontremos?",
  ui_story_2001_4_17_dialog_content = "Se supone que es la hora de mi siesta. Un horario de descanso desordenado lleva a eventos desagradables...",
  ui_story_2001_4_18_dialog_content = "Habría terminado pronto para ti, acabando con tu dolor. ¿Por qué escapar?",
  ui_story_2001_4_19_dialog_content = "Podrías haberte despedido de todos estos, y envidiaría eso.",
  ui_story_2001_4_20_dialog_content = "Rayos. ¡Hay compañía, Jona! ¿Esas dos son...?",
  ui_story_2001_4_21_dialog_content = "¡Los Ángeles Guardianes de los Caballeros! Veo que las historias son ciertas...",
  ui_story_2001_4_22_dialog_content = "Que no te engañe su apariencia, son incluso...",
  ui_story_2001_4_23_dialog_content = "...¡más lindas que en las historias!",
  ui_story_2001_4_24_dialog_content = "¿Ah?",
  ui_story_2001_4_25_dialog_content = "Al ver cómo Lumopolis desperdicia los abundantes recursos de la civilización antigua y atiende a las élites en las nubes, pensé que Lumopolis es simplemente el pozo del libertinaje.",
  ui_story_2001_4_26_dialog_content = "¡Ciertamente no esperé que sus Caballeros tuvieran tantas bellas damas de batalla! Qué desperdicio...",
  ui_story_2001_4_27_dialog_content = "¿Hola, son enemigas las que tenemos aquí? No me importa si son chicas bellas o demonios del infierno...",
  ui_story_2001_4_28_dialog_content = "No tendrás muchas oportunidades para hablar con chicas lindas, Brock. Deberías apreciar esto.",
  ui_story_2001_4_29_dialog_content = "¡N-no es de tu incumbencia! ¡Jona! ¡Creo que hacen un movimiento!",
  ui_story_2001_4_30_dialog_content = "<color=#e8d9bb>Su ataque pasó delante de Brock, destrozando el dirigible y cualquier esperanza de escapar en él.</color>",
  ui_story_2001_4_31_dialog_content = "¡Rayos, el dirigible...!",
  ui_story_2001_4_32_dialog_content = "¡Tee hee! ¿Qué energéticos invitados, no crees, querida Uriela? ¿Puedo... Disfrutar esto un poco más...?",
  ui_story_2001_4_33_dialog_content = "Basta, Gabriela. Antes de que vengan más guardias...",
  ui_story_2001_4_34_dialog_content = "...Enviémoslos a...el eterno descanso.",
  ui_story_2001_4_35_dialog_content = "¡Jajajajajaja!",
  ui_story_2001_4_36_dialog_content = "¡De acuerdo, no he tenido mucha acción en un rato! ¡No se queden paradas, ustedes dos chicas tienen que mantener el paso también!",
  ui_story_2001_4_37_dialog_content = "Resoplan...",
  ui_story_2001_4_38_dialog_content = "Sí, fácil para ti decirlo... ¿Qué? ¡Ustedes son...!",
  ui_story_2001_4_39_dialog_content = "<color=#e8d9bb>Dos figuras familiares descendieron de nuevo ante un Brock debilitado.</color>",
  ui_story_2001_4_40_dialog_content = "...",
  ui_story_2001_4_41_dialog_content = "¡Espera, espérame Michele! Tus heridas apenas han sanado, correr tan rápido va a...",
  ui_story_2001_4_42_dialog_content = "Quizás quieras revisar tus ojos... Obviamente es una chica.",
  ui_story_2001_4_43_dialog_content = "¡Yeowww! ¡Hoy debe ser mi día de suerte! ¡Cuatro Ángeles en un solo lugar!",
  ui_story_2001_4_44_dialog_content = "¿El Apocalipsis, dices? Enfrentándonos a las cuatro a la vez, incluso cuando somos tú y yo ...",
  ui_story_2001_4_45_dialog_content = "¡Yo me encargaré, Jona! Mira si puedes encontrar a otros cerca...",
  ui_story_2001_4_46_dialog_content = "Guarda el discurso pesimista y fatal para otro día, ¿que tal? Te dije que te sacaría de aquí, sería vergonzoso si no lo hiciera.",
  ui_story_2001_4_47_dialog_content = "El viaje lo vale. ¡No esperaba menos de Lumopolis!",
  ui_story_2001_4_48_dialog_content = "Ahora entiendo por qué tantos bobos vienen aquí con la ilusión de ser elegidos un día.",
  ui_story_2001_4_49_dialog_content = "Afortunadamente, es más fácil salir.",
  ui_story_2001_4_50_dialog_content = "<size=45>¡Adiós, pequeñas ángeles!</size>",
  ui_story_2001_4_51_dialog_content = "<color=#e8d9bb>Jona tomó a Brock y <color=#FFB400>saltó</color></color> del borde del centro.",
  ui_story_2001_4_52_dialog_content = "<color=#e8d9bb>La abrupta ingravidez envió escalofríos a todas sus células.</color>",
  ui_story_2001_4_53_dialog_content = "La comida y el alojamiento pueden mejorar ¡sin embargo, pulgar arriba por el servicio! ¡Hasta la próxima!",
  ui_story_2001_4_54_dialog_content = "¡Arghhhhh!",
  ui_story_2001_4_55_dialog_content = "<size=45>¡¡Vamos a morir–!!</size>",
  ui_story_2001_4_56_dialog_content = "<color=#e8d9bb>Brock gritó y se sofocó mientras su visión se volvió negra...</color>",
  ui_story_2001_5_1_dialog_content = "...",
  ui_story_2001_5_2_dialog_content = "Oye, ¿vas a dejar esa actitud pronto? ¿Ya me disculpé, no?",
  ui_story_2001_5_3_dialog_content = "No estoy...",
  ui_story_2001_5_4_dialog_content = "Qué cobarde. Nunca había escuchado un chillido tan miserable.",
  ui_story_2001_5_5_dialog_content = "¡Temo a las alturas! ¡¿Y quién sería tan loco para saltar de Lumopolis de todos modos?!",
  ui_story_2001_5_6_dialog_content = "Tienes que sorprenderte a ti mismo antes de sorprender al enemigo.",
  ui_story_2001_5_7_dialog_content = "Seguro no lo esperaban ¿cierto? ¡Puedes llamarlo improvisación de Rediesel Wrench! ¡Eh!",
  ui_story_2001_5_8_dialog_content = "¿Improvisación? ¿Era en serio cuando dijiste que aterrizamos sanos, gracias a la fuerza del culatazo de la pistola?",
  ui_story_2001_5_9_dialog_content = "El culatazo probablemente tuvo que ver con eso, seguro, pero sobre todo...",
  ui_story_2001_5_10_dialog_content = "¿Tu poderosa Lumina, a pesar de ser restringida por las esposas?",
  ui_story_2001_5_11_dialog_content = "¡Principalmente SUERTE! ¡Wajajajaja!",
  ui_story_2001_5_12_dialog_content = "Eres la primera que mataré en cuanto releve a Sinsa.",
  ui_story_2001_5_13_dialog_content = "¿En serio? No puedo esperar, entonces. Por supuesto, eso depende de que viva lo suficiente para que eso ocurra finalmente.",
  ui_story_2001_5_14_dialog_content = "¿Qué tal si vamos rumbo a Umbraton a tomar algo? Quizás incluso pidamos un aventón...",
  ui_story_2001_5_15_dialog_content = "¡Oye, por allá, parece una bandera de<color=#FFB400> Tornillos Sueltos</color>!",
  ui_story_2001_5_16_dialog_content = "Veo que pasaron un buen tiempo, y Jona incluso parece que ganó peso.",
  ui_story_2001_5_17_dialog_content = "¡Sin embargo, lo que me molesta es que me dejes fuera de las divertidas peleas en Lumopolis!",
  ui_story_2001_5_18_dialog_content = "¡Ja, incluso pudimos ver a las cuatro ángeles al mismo tiempo! ¡No es cierto, Brock!",
  ui_story_2001_5_19_dialog_content = "Em, sí...",
  ui_story_2001_5_20_dialog_content = "¿Qué le pasa a este tipo, no tomó cereal hoy?",
  ui_story_2001_5_21_dialog_content = "Olvídalo. El grandote me envió a buscarte, mientras te traiga de vuelta en una pieza...",
  ui_story_2001_5_22_dialog_content = "Sinsa de verdad actúa como si fuera el jefe de vez en cuando, ya veo.",
  ui_story_2001_5_23_dialog_content = "Para ser exacta, todos tenían ganas de ir al restaurante de ramen de Umbraton, así que podrían ver si te recogen ya que estabas en el camino.",
  ui_story_2001_5_24_dialog_content = "De todos modos, según las observaciones de los técnicos, este lugar debería estar repleto de Eclipsites muy pronto.",
  ui_story_2001_5_25_dialog_content = "¿Muy pronto?",
  ui_story_2001_5_26_dialog_content = "Eso dijo Odi cuando me fui.",
  ui_story_2001_5_27_dialog_content = "¿Significa que casi es hora del show?",
  ui_story_2001_5_28_dialog_content = "¡Deberíamos largarnos! No estamos en forma para lidiar con los Eclipsites ahora...",
  ui_story_2001_5_29_dialog_content = "¿Con la cola entre las piernas ahora?",
  ui_story_2001_5_30_dialog_content = "¡No, se llama sentido común, sentido común! ¿Y qué no tenemos a Lumopolis pisándonos los talones?",
  ui_story_2001_5_31_dialog_content = "Oh, ellos... Ya están aquí y preparando una emboscada.",
  ui_story_2001_5_32_dialog_content = "¡¿Qué?!",
  ui_story_2001_5_33_dialog_content = "Bien, los Cabezas Blancas pueden salir ahora. Los Eclipsites están listos para saltar, así que terminemos con esto rápido, ¿bien?",
  ui_story_2001_6_1_dialog_content = "¡Vengan a mí, todos ustedes, los mandaré a volar!",
  ui_story_2001_6_2_dialog_content = "Brock seguro mejoró rápido... ¡Oye, cuidado con la arena movediza..!",
  ui_story_2001_6_3_dialog_content = "Uups. Demasiado tarde.",
  ui_story_2001_6_4_dialog_content = "Tuviste “vacaciones” y te tomas más tiempo ahora, ¿Jona?",
  ui_story_2001_6_5_dialog_content = "<color=#e8d9bb>La temperatura bajó drásticamente de repente, levantando los pelos de la nuca de todos.</color>",
  ui_story_2001_6_Q1_dialog_content = "Bien, parece que estamos atrapados con los Eclipsites, después de todo. Hora de ponerse serios.",
  ui_story_2001_6_Q2_dialog_content = "¿Eclipsites? Grr... ¡Qué molestia! Si tan solo estos Cabezas Blancas no nos atrasaran...",
  ui_story_2001_6_Q3_dialog_content = "Espera, ¿una gran pelea destrozaría el vecindario... y nuestro restaurante de ramen, también?",
  ui_story_2001_6_Q4_dialog_content = "Necesitas ordenar tus prioridades Regina.",
  ui_story_2001_6_6_dialog_content = "Deberías ver por allá. ¿Qué es lo que se acerca entre los Eclipsites?",
  ui_story_2001_6_7_dialog_content = "No distingo si será un oponente difícil desde aquí...",
  ui_story_2001_6_8_dialog_content = "¡Gahhhhhh!",
  ui_story_2001_6_9_dialog_content = "<color=#e8d9bb>Mientras tanto,</color>",
  ui_story_2001_6_10_dialog_content = "<color=#e8d9bb>los Guardianes de Lumopolis, que perseguían a Brock, se vieron envueltos en una batalla con la horda Eclipsite en su lugar.</color>",
  ui_story_2001_6_11_dialog_content = "¡Manténganse firmes! ¡Ángeles primero, seguidas por escuadrones 3 y 7!",
  ui_story_2001_6_12_dialog_content = "¡El resto de ustedes están en espera y esperan mi orden!",
  ui_story_2001_6_13_dialog_content = "¡Capitana! ¡El objetivo ha roto nuestra formación y se mueve hacia el campamento!",
  ui_story_2001_6_14_dialog_content = "¡Los enemigos nos bloquearon las tropas! ¡También perdimos comunicación debido a interferencia!",
  ui_story_2001_6_15_dialog_content = "Capitana Carleen, si las cosas siguen así...",
  ui_story_2001_6_16_dialog_content = "Vaya, vaya, ¡qué fiesta tan animada aquí! ¿Podemos unirnos, sí, princesa de los Guardianes?",
  ui_story_2001_6_17_dialog_content = "¡Bien, ya que me perdí la diversión arriba, esto lo hará!",
  ui_story_2001_6_18_dialog_content = "¿Cómo se atreven mostrarse ante mí?",
  ui_story_2001_6_19_dialog_content = "Deja de gruñir, querida. No tenemos tiempo de coquetear ahora.",
  ui_story_2001_6_20_dialog_content = "¡Por qué tú...!",
  ui_story_2001_6_21_dialog_content = "¡Ja! ¡Ese grandote es todo mío, si vas a seguir parloteando!",
  ui_story_2001_6_22_dialog_content = "¡Sigue soñando, ese es mi trofeo!",
  ui_story_2001_6_23_dialog_content = "¡Oigan, oigan, están saltando el arma! ¡Eso es trampa! ¡Regresen aquí!",
  ui_story_2001_6_24_dialog_content = "<color=#e8d9bb>El dúo bromeó mientras se lanzaba temerariamente a la escaramuza entre los Eclipsites y los guardianes...</color>",
  ui_story_2001_6_25_dialog_content = "Cap-capitana, parece que hay una apertura. Los Eclipsites han sido dispersados por esos dos...",
  ui_story_2001_6_26_dialog_content = "<color=#e8d9bb>Al ver que los intrépidos destrozaban la horda Eclipsite, Carleen se volteó y dio una orden a los Guardianes.</color>",
  ui_story_2001_6_27_dialog_content = "¡Todos a la carga! ¡Rompan sus filas!",
  ui_story_2001_6_28_dialog_content = "No me hagas caer, princesa.",
  ui_story_2001_6_29_dialog_content = "¡Esa es mi línea, terrorista! ¡Aquí voy!",
  ui_story_2001_6_30_dialog_content = "¡Phew! No más Eclipsites a la vista. Supongo que podemos darlo por terminado y Lumopolis apenas pasa la prueba, redondeado.",
  ui_story_2001_6_31_dialog_content = "Todas las unidades, cuenten las bajas e inicien el protocolo de primera respuesta. Quiero los reportes al final del día. Cambio.",
  ui_story_2001_6_32_dialog_content = "Parece que ser capitán es trabajo duro también. ¡Dejaré que te ocupes y te veré después!",
  ui_story_2001_6_33_dialog_content = "Alto.",
  ui_story_2001_6_34_dialog_content = "Jona, miembro de los Rediesel Wrench, por escapar de prisión y causar pérdidas masivas en Lumopolis, vengo a...",
  ui_story_2001_6_35_dialog_content = "¿Me estás arrestando? Siempre serás plana como una tabla si te pones así, princesa.",
  ui_story_2001_6_36_dialog_content = "Altanera delincuente, pagarás caro tu insolencia...",
  ui_story_2001_6_37_dialog_content = "<color=#e8d9bb>Antes de que Carleen pudiera terminar, el suelo empezó a temblar a un ritmo como si algo se acercaba. Instintivamente tomó posición de batalla, solo para ver...</color>",
  ui_story_2001_6_38_dialog_content = "<size=45>Oye.</size>",
  ui_story_2001_6_39_dialog_content = "¿Qué te tomó tanto, grandulón?",
  ui_story_2001_6_40_dialog_content = "Jaja, nada puede despertarme de mi siesta de la tarde.",
  ui_story_2001_6_41_dialog_content = "¿Eres Sinsa? El líder de Rediesel Wrench...",
  ui_story_2001_6_42_dialog_content = "Así es, soy su líder. Dale gracias a todos en Lumopolis por cuidar de ellos por mí.",
  ui_story_2001_6_43_dialog_content = "¿Crees que puedes irte así? ¡Ni lo pienses!",
  ui_story_2001_6_44_dialog_content = "No te molestes, princesita. Mira a tus soldados primero. No estés triste, nos veremos de nuevo cuando extrañe las comidas de Lumopolis.",
  ui_story_2001_6_45_dialog_content = "¡Detente!",
  ui_story_2001_6_46_dialog_content = "<color=#e8d9bb>Carleen trató de perseguirlos pero, por alguna razón, sus pies eran tan pesados como el plomo y sólo pudo ver a los Rediesel Wrench alejarse...</color>",
  ui_story_2001_6_47_dialog_content = "¡He estado buscándote por todas partes, Carleen! ¡No deberías salir corriendo cuando estás lesionada!",
  ui_story_2001_6_48_dialog_content = "¿Qué tiene que ver eso con la altura, de todos modos?",
  ui_story_2001_6_49_dialog_content = "¿Hmm? ¿Qué dijiste?",
  ui_story_2001_6_50_dialog_content = "Nada. Vamos a casa.",
  ui_story_2001_6_51_dialog_content = "Pero te prometo, habrá venganza.",
  ui_story_2002_1_1_dialog_content = "...",
  ui_story_2002_1_2_dialog_content = "...¿Eh?",
  ui_story_2002_1_3_dialog_content = "¡Ay! ¡¡¡Mi cola!!!",
  ui_story_2002_1_4_dialog_content = "<color=#e8d9bb>La Subciudad permaneció en silencio mientras descansaban. Sharona despertó de su sueño con la sensación de que alguien— o algo —estaba tocando su cola...</color>",
  ui_story_2002_1_5_dialog_content = "<color=#e8d9bb>La figura de una persona que parecía ser experta en ocultar su identidad se balanceaba en las sombras.\nSin embargo, esto convenció a Sharona de que una persona era responsable de esta broma.</color>",
  ui_story_2002_1_6_dialog_content = "¿Quién eres, niño? ¡Cómo te atreves a tocar mi cola mientras duermo!",
  ui_story_2002_1_7_dialog_content = "...",
  ui_story_2002_1_8_dialog_content = "¿Un Eclipsite? ¿De dónde saliste? Esos guardias de turno deben pedir un poco de entrenamiento extra...",
  ui_story_2002_1_9_dialog_content = "Espera... Ese olor peculiar... Puedo oler algo más.",
  ui_story_2002_1_10_dialog_content = "¡Oye! ¿Eres un Eclipsite o un Aurorian? ¡Te daré un minuto para responderme, así que di algo si me entiendes!",
  ui_story_2002_1_11_dialog_content = "...¿Por qué atacaste mi cola?",
  ui_story_2002_1_12_dialog_content = "Suelta la sopa y quizás te deje vivir por otro minuto.",
  ui_story_2002_1_13_dialog_content = "<color=#e8d9bb>La figura permaneció en las sombras, emitiendo ruidos ininteligibles en la oscuridad.</color>",
  ui_story_2002_1_14_dialog_content = "No podemos comunicarnos. Me pareces más bien un Eclipsite, así que no me culpes por esto—",
  ui_story_2002_1_15_dialog_content = "...jajajajaja...",
  ui_story_2002_1_16_dialog_content = "¿E-estás riéndote? ¿Qué eres? ¿Me entiendes?",
  ui_story_2002_1_17_dialog_content = "Jajaja... ¡Ajajajajaja! Eres inesperadamente linda cuando estás confundida...",
  ui_story_2002_1_18_dialog_content = "Quiero un regalo tuyo cuando nos veamos la próxima vez...",
  ui_story_2002_1_19_dialog_content = "¡¿Universés?! ¡Espera!",
  ui_story_2002_1_20_dialog_content = "¡Argh! Lo perdí.",
  ui_story_2002_1_21_dialog_content = "Este olor... Huele como la aura de un Eclipsite y...¿pólvora?",
  ui_story_2002_1_22_dialog_content = "Urgh...",
  ui_story_2002_1_23_dialog_content = "¿Has estado aquí por un tiempo? ¿Así que esa cosa era tu jefe? ¿Ella en realidad deja a sus subordinados morir así? Qué chiste.",
  ui_story_2002_1_24_dialog_content = "Desahogaré mi frustración con los pequeños como tú hasta que logre encontrar a tu jefe.",
  ui_story_2002_1_25_dialog_content = "Esas bombas y Eclipsites eran tan débiles... Apenas logré hacer ejercicio con ellos.",
  ui_story_2002_1_26_dialog_content = "¿Sharona? ¿Qué haces aquí tan temprano? Qué es este desorden... ¿Estuviste peleando con alguien?",
  ui_story_2002_1_27_dialog_content = "Algunos peones de la oscuridad estaban escondidos afuera, así que vine a deshacerme de ellos.",
  ui_story_2002_1_28_dialog_content = "Parece que necesitas ayuda. ¿Qué tal una taza de café?",
  ui_story_2002_1_29_dialog_content = "Está bien... Pensándolo bien, la tomaré.",
  ui_story_2002_1_30_dialog_content = "Eso es extraño—no debes haber dormido bien. Creí escuchar una explosión mientras dormía. ¿Estás segura que todo está bien?",
  ui_story_2002_1_31_dialog_content = "¿Mientras dormías? ¿Te las arreglaste para vestirte tan bien en tan poco tiempo antes de salir corriendo a ver qué pasa? De esperarse de nuestra jefe de personal.",
  ui_story_2002_1_32_dialog_content = "¿Oh? Qué sorprendente. Gracias por el halago. ¿Le agrego más azúcar a tu café?",
  ui_story_2002_1_33_dialog_content = "Cómo sea, no me importa. Por cierto, ¿puedes reunir a todos aquí?",
  ui_story_2002_1_34_dialog_content = "¿Oh? Suena a algo serio.",
  ui_story_2002_1_35_dialog_content = "No realmente, pero no creo que sea tan simple tampoco. Solo espero que nada salga mal.",
  ui_story_2002_1_36_dialog_content = "Pero acabo de ver tu cola golpeando el suelo con impaciencia. ¿Estás segura que no es nada serio?",
  ui_story_2002_1_37_dialog_content = "...olvida lo que viste. No quiero repetir lo que dije.",
  ui_story_2002_1_38_dialog_content = "...eso es todo. Ese Eclipsite no identificado definitivamente nos atacará de nuevo, así que debemos estar atentos. He terminado. La reunión ha terminado.",
  ui_story_2002_1_39_dialog_content = "Ugh... Hay tanta gente aquí. ¿Cómo duermo lo suficiente cuando la reunión es tan temprano en la mañana?",
  ui_story_2002_1_40_dialog_content = "Llegas tarde, Philyshy.",
  ui_story_2002_1_41_dialog_content = "¡No seas mala! Sólo me quedé dormida un poco.",
  ui_story_2002_1_42_dialog_content = "¿Cinco minutos más? ¿Quieres repetirlo?",
  ui_story_2002_1_43_dialog_content = "¡Relájese, señora! Como dicen, los primeros 5 minutos de una reunión son sólo el calentamiento. Debo haber llegado a tiempo para los problemas importantes...",
  ui_story_2002_1_44_dialog_content = "Tu... La reunión ya ha terminado.",
  ui_story_2002_1_45_dialog_content = "¡Oh! ¿En serio? ¡Miau! No puede evitarse.. Tendré que volver a ir a dormir... Tengo tanto sueño...",
  ui_story_2002_1_46_dialog_content = "Vivian, ¿esta es tu subordinada?",
  ui_story_2002_1_47_dialog_content = "¿Qué?",
  ui_story_2002_1_48_dialog_content = "¿Este es tu subordinada?",
  ui_story_2002_1_49_dialog_content = "Ah, em, sí... Ella es...",
  ui_story_2002_1_50_dialog_content = "¿Necesitas preguntar? ¿Vamos, señora, no reconoces a tus colegas?",
  ui_story_2002_1_51_dialog_content = "¡Cuida tus modales!",
  ui_story_2002_1_52_dialog_content = "¡Oh! ¡Vivian esta taaaan feroz hoy! ¡Sonríe! Te saldrán arrugas si frunces mucho el ceño, miau.",
  ui_story_2002_1_53_dialog_content = "No sabía que Illumina tiene a una miembro tan perezosa. ¿Cómo es posible que recuerde a alguien así? Deberías tomar un momento para reflexionar.",
  ui_story_2002_1_54_dialog_content = "Lo siento... Me va a tener que escuchar. No te enojes...",
  ui_story_2002_1_55_dialog_content = "¿Oye, por qué me deben regañar? Solo llegué un poquito tarde...",
  ui_story_2002_1_56_dialog_content = "¡Eso es ridículo! Tu eres—",
  ui_story_2002_1_57_dialog_content = "¡Ah! ¡Ya que he hecho café, por qué no tomamos un descanso por ahora y nos olvidamos de estas cosas triviales!\n...Philyshy, estás en patrulla nocturna hoy.",
  ui_story_2002_1_58_dialog_content = "¿¡Qué!? Eso significa que Philyshy... no significa que no puedo d—",
  ui_story_2002_1_59_dialog_content = "¡PATRULLA NOCTURNA! ¿Me entiendes? ¡¿Necesito repetirlo una vez más en tus orejas?!",
  ui_story_2002_1_60_dialog_content = "Bien, bien—no hay necesidad de gritarle a Philyshy... Lo haré...",
  ui_story_2002_1_61_dialog_content = "No le hagas caso, Sharona. Aunque Philyshy es un poco desaliñada, confía en el ojo de Reinhardt para el talento. Te garantizó que ella es de mucha ayuda.",
  ui_story_2002_1_62_dialog_content = "Es tu subordinada, pero creo que entiendes que...",
  ui_story_2002_1_63_dialog_content = "Illumina no necesita ningún inútil.",
  ui_story_2002_2_1_dialog_content = "...",
  ui_story_2002_2_2_dialog_content = "...¿Eh?",
  ui_story_2002_2_3_dialog_content = "¡Ay! ¡¡¡Mi cola!!!",
  ui_story_2002_2_4_dialog_content = "...",
  ui_story_2002_2_5_dialog_content = "¡Cielos! ¡Eres tú de nuevo! Si eres capaz de infiltrarte en la Subciudad, ¿por qué pierdes tanto esfuerzo sólo para atacar mi cola y...?",
  ui_story_2002_2_6_dialog_content = "¿Por qué estás realmente aquí?",
  ui_story_2002_2_7_dialog_content = "...",
  ui_story_2002_2_8_dialog_content = "¿Oye, será que estás transmitiendo señales a otros? Deja de hablar con tus amigos Eclipsites por ahora. ¿Cuál es el punto de convocar a un grupo de pequeños enclenques aquí?",
  ui_story_2002_2_9_dialog_content = "La puerta está cerrada.. Te doy un minuto. Explica tus intenciones, y consideraré matarte rápidamente.",
  ui_story_2002_2_10_dialog_content = "...jajajajaja... ¡Qué impaciente!",
  ui_story_2002_2_11_dialog_content = "¡Lo sabía! Así que hablas Universés... ¿¡Por qué tienes el olor de un Aurorian en ti!? Eres un Aurorian o un—no, con un aura así, debes ser un Eclipsite.",
  ui_story_2002_2_12_dialog_content = "Solo acuéstate tranquila y deja que agarre tu cola. ¡No es divertido cuando haces esto!",
  ui_story_2002_2_13_dialog_content = "¿Así que te gusta mi cola, eh? ¿Qué? ¿Ustedes Eclipsites la necesitan para algo en particular?",
  ui_story_2002_2_14_dialog_content = "Es para diversión.",
  ui_story_2002_2_15_dialog_content = "¿Ah? Que rayos... ¡Cómo no dirás la verdad, tendré que capturarte e interrogarte!",
  ui_story_2002_2_16_dialog_content = "¡Ja! ¡Fallaste! ¿Será porque apenas estás despierta? Nos veremos de nuevo, pequeño dragón tonto.",
  ui_story_2002_2_17_dialog_content = "¡Tonto! ¡Ey espera! ¡¿A dónde crees que vas?!",
  ui_story_2002_2_18_dialog_content = "<color=#e8d9bb>Fuera de la sala de Intel. de Illumina</color>",
  ui_story_2002_2_19_dialog_content = "...¿dónde está?",
  ui_story_2002_2_20_dialog_content = "¡Ja! Eres tan puntual. El plan está yendo suuuuuper bien... Oye, hablando del plan, ¿qué querías que encontrara?\nUn super poderoso y gran—",
  ui_story_2002_2_21_dialog_content = "...un catalizador explosivo.",
  ui_story_2002_2_22_dialog_content = "Sí, sí, sí, ese es. Eso y... ¡la cola del tonto dragón!",
  ui_story_2002_2_23_dialog_content = "...¿cola? Oye, más vale que sea bueno y completes la misión. Sabes lo que pasará si surgen nuevos problemas, ¿verdad?\n¡El maestro no te perdonará fácilmente!",
  ui_story_2002_2_24_dialog_content = "Yo, Bowlinger, soy responsable de la parte más crucial del plan del maestro para destruir Illumina. Si fallamos desarrollar algo lo suficientemente poderoso para cuando ataquemos—",
  ui_story_2002_2_25_dialog_content = "Ejem, casi he dicho algo que no debería... ¡Cómo sea, necesito que encuentres un catalizador que aumente mucho el daño del ataque!",
  ui_story_2002_2_26_dialog_content = "Sr. Bowlinger, se supone que somos socios, ¿por qué no compartes información conmigo? Tuve que esforzarme mucho para encontrar este \"núcleo de energía\".",
  ui_story_2002_2_27_dialog_content = "¡Ohhh! ¿Núcleo de energía? ¿Es la nueva tecnología de Illumina?",
  ui_story_2002_2_28_dialog_content = "...Espera, ¿es este el envase? ¡Es una pepita de oro del tamaño de una palma!",
  ui_story_2002_2_29_dialog_content = "¡No subestimes el envase! ¡Adentro se encuentra un dispositivo súper núcleo \"MAX Bang\" con poder ilimitado que yo misma he experimentado!\n¡Debes tener mucho cuidado!",
  ui_story_2002_2_30_dialog_content = "Asegúrate de no abrirlo antes de que necesites usarlo, porque es volátil y antes de que te des cuenta, desaparece.",
  ui_story_2002_2_31_dialog_content = "¿Volátil? ¿Te refieres que disipa energía? ¡¿O una reacción aún más peligrosa?! ¡¡Me estoy emocionando!!",
  ui_story_2002_2_32_dialog_content = "Como sea, solo necesitas confiar en mí. Con esto, Sr. Bowlinger, sus preparativos están completos...",
  ui_story_2002_2_33_dialog_content = "¡Bien! ¡Le pediré a alguien que venga por él ahora! No esperaba que alguien tan poco confiable como tú lo lograra.\n¡Hablaré bien de ti delante de esa persona!",
  ui_story_2002_2_34_dialog_content = "Muchas gracias, Sr. Bowlinger. Recuerda, no abras su núcleo de energía hasta el último momento—",
  ui_story_2002_2_35_dialog_content = "¿Estas bromeando? ¿Lo perdiste de nuevo? ¿Cómo lograron acercarse tanto a nosotros estos Eclipsites? ¿Tomaron un atajo?",
  ui_story_2002_2_36_dialog_content = "Su líder debe ser responsable de esto. Ella intencionalmente envió un grupo de enclenques Eclipsites a morir aquí...",
  ui_story_2002_2_37_dialog_content = "¡¿Está tratando de atraerme lejos de aquí?! Si su propósito es atraerme lejos de la entrada de la Subciudad,",
  ui_story_2002_2_38_dialog_content = "Significa que su objetivo principal es... El lugar más cercano es el Departamento de Inteligencia, y la única de guardia nocturna es...",
  ui_story_2002_2_39_dialog_content = "¡¡Philyshy!!",
  ui_story_2002_2_40_dialog_content = "Phew... Está tan callado aquí. Parece que nada ha pasado aún.",
  ui_story_2002_2_41_dialog_content = "<color=#e8d9bb>Sin embargo, una figura familiar vestida de blanco estaba apoyada en la puerta abierta de la sala de inteligencia y parecía inconsciente—</color>",
  ui_story_2002_2_42_dialog_content = "¡P-Philyshy! ¡¿Estás bien?! Podría haber sido atacada...",
  ui_story_2002_2_43_dialog_content = "¡¡Convoca a los doctores!!",
  ui_story_2002_2_44_dialog_content = "...así que, ¿solo dormías?",
  ui_story_2002_2_45_dialog_content = "...Philyshy...Philyshy estaba muy somnolienta... De ningún modo, Sr., me está diciendo que es contra la ley dormir...",
  ui_story_2002_2_46_dialog_content = "Si no te atacaron, por qué estaba abierta así la puerta de la sala de inteligencia...",
  ui_story_2002_2_47_dialog_content = "Mmmm... Philyshy no tiene idea...",
  ui_story_2002_2_48_dialog_content = "Como sea, déjame ver si estás herida.",
  ui_story_2002_2_49_dialog_content = "No te molestes. Ella está bien. Se supone que es una gata, pero duerme como un...",
  ui_story_2002_2_50_dialog_content = "¿Vivian, encontraste a la persona que describí? También puede haber un atajo escondido que el enemigo estaría usando para ocultar su operación.",
  ui_story_2002_2_51_dialog_content = "No tengo pistas. Si se trata de un que puede escapar de ti, no creo que los soldados ordinarios tengan una oportunidad contra él.",
  ui_story_2002_2_52_dialog_content = "Me pregunto qué es lo que quiere... Todo lo que hizo fue hacer un desorden en la cocina del Depto. de Inteligencia. Nada parece faltar, y Philyshy no estaba herida.",
  ui_story_2002_2_53_dialog_content = "No sé. La persona que vi era simplemente inexplicable... No sé qué pensar al respecto.",
  ui_story_2002_2_54_dialog_content = "Lo siento, tenía tanto sueño, así que... me dormí...",
  ui_story_2002_2_55_dialog_content = "No estábamos planeando en culparte, pero tu... al menos deberías ser más seria cuando te disculpes.",
  ui_story_2002_2_56_dialog_content = "Vamos, solo tomé una pequeña siesta... Deberías saber que no puedo quedarme despierta cuando tengo sueño, y anoche me dormí tarde también.",
  ui_story_2002_2_57_dialog_content = "¿Así que, la sala de Inteligencia fue profanada porque dormías? ¿El enemigo pudo entrar así descaradamente?\nNi siquiera Reinhardt tomaría tu lado si se entera de esto—",
  ui_story_2002_2_58_dialog_content = "Um... Sharona, acabo de contactar a Reinhardt, y tiene unas instrucciones.",
  ui_story_2002_2_59_dialog_content = "¡¿Este asunto la alarmó?! T-todo esto es mi culpa... Esto no habría pasado si hubiera logrado atrapar a esa criatura... Fallé mi misión.",
  ui_story_2002_2_60_dialog_content = "Descuida, no está enojada. Nos dijo que continuáramos investigando qué se perdió y cuál es el objetivo del enemigo.",
  ui_story_2002_2_61_dialog_content = "Voy a cooperar con ella en algunos interrogatorios internos, pero necesitarán continuar con las investigaciones externas.",
  ui_story_2002_2_62_dialog_content = "Entiendo. Asegúrale que puede confiarme este asunto.",
  ui_story_2002_2_63_dialog_content = "También, ella quisiera que tuvieras un asistente—",
  ui_story_2002_2_64_dialog_content = "¿Un asistente? No, ella debería saber que soy capaz de lidiar con esto por mi cuenta. Por qué habría—",
  ui_story_2002_2_65_dialog_content = "No digas esto en un momento así, Sharona. El enemigo es muy poderoso...",
  ui_story_2002_2_66_dialog_content = "Pero tú sabes que las cosas empeorarán si alguien se mete en mi camino.",
  ui_story_2002_2_67_dialog_content = "Peor, en realidad, ella ya ha asignado a alguien—",
  ui_story_2002_2_68_dialog_content = "<color=#e8d9bb>En ese momento, Vivian miró a Philyshy, que seguía somnolienta, con una expresión complicada. Philyshy se congeló por un momento antes de poder regresar a sus sentidos.</color>",
  ui_story_2002_2_69_dialog_content = "...¿eh? ¿¿La jefe quiere que vaya??",
  ui_story_2002_2_70_dialog_content = "Sí, necesitas ir con Sharona e investigar todo. Haz eso y no serás castigada por lo que pasó hoy.",
  ui_story_2002_2_71_dialog_content = "<color=#e8d9bb>Ambas Sharona y Philyshy se quedaron mudas después de oír esto. Se miraron de reojo, pero ninguna dijo una palabra...</color>",
  ui_story_2002_3_1_dialog_content = "¡Sharona—no, debería llamarte Líder de ahora en adelante, miau! ¿Estás enojada?",
  ui_story_2002_3_2_dialog_content = "Líder, no estés enojada... ¡Te prometo que ayudaré! ¡Líder, te ves tan fuerte!\n¡Haré todo lo posible por igualarte!",
  ui_story_2002_3_3_dialog_content = "¡Ah! ¡Es tan aterrador aquí! ¿Líder, puedes mantenerte cerca de mi...?",
  ui_story_2002_3_4_dialog_content = "¿Líder, como llegaste a ser tan fuerte sin verte tan muscular? ¿Tienes una forma especial de entrenar tus músculos?",
  ui_story_2002_3_5_dialog_content = "¡Líder! ¡Tus cuernos y cola son muy especiales! ¿Lo puedo tocar? ¿Puedo? ¿Puedo?",
  ui_story_2002_3_6_dialog_content = "¡Cállate! Eres muy ruidosa.",
  ui_story_2002_3_7_dialog_content = "¿Por qué estás tan molesta conmigo? ¿Y por qué corres tan rápido? ¡No puedo seguir! ¡Despacio!",
  ui_story_2002_3_8_dialog_content = "...¿no sientes nada de remordimiento? Esto no habría pasado si no hubieras estado durmiendo mientras estabas de turno—",
  ui_story_2002_3_9_dialog_content = "¿Miau? Lo siento, pero estaba muy somnolienta hoy, y no podía quedarme despierta. ¡Sin mencionar que tengo una oportunidad de hacer bien las cosas!\nPhilyshy no sabe nada de nada...",
  ui_story_2002_3_10_dialog_content = "Oh no, tengo sueño de nuevo...",
  ui_story_2002_3_11_dialog_content = "...inútil.",
  ui_story_2002_3_12_dialog_content = "...¿oh? ¿Qué es eso?",
  ui_story_2002_3_13_dialog_content = "<color=#e8d9bb>Algo llamó la atención de Philyshy. Caminó hacia una horca sola</color>",
  ui_story_2002_3_16_dialog_content = "¿Es un enemigo? Mmm, no lo es... ¿Me equivoqué?",
  ui_story_2002_3_17_dialog_content = "Creí haber sentido algo justo ahora, pero el aura desapareció.",
  ui_story_2002_3_18_dialog_content = "No hay camino adelante. Oye, Philyshy, tenemos—",
  ui_story_2002_3_19_dialog_content = "¿Philyshy?",
  ui_story_2002_3_20_dialog_content = "¿Ella se fue? ¡Sabía que no debería haberla traído!",
  ui_story_2002_3_21_dialog_content = "Cielos... Ahora tendré que salvarla antes de poder completar la misión. Reinhardt definitivamente se molestará conmigo si la dejo sola...\n¡Argh! ¡Qué dolor de cabeza!",
  ui_story_2002_3_22_dialog_content = "¡Oye! ¡Escuché todo, miau! Dijiste que me salvarías antes de completar la misión...",
  ui_story_2002_3_23_dialog_content = "¡¿Tu?! ...¿a dónde te fuiste?",
  ui_story_2002_3_24_dialog_content = "No lo sé tampoco. ¡De alguna manera encontré esta entrada rara! Parece que va a un lugar extraño.\n¡Continuemos desde aquí!",
  ui_story_2002_3_25_dialog_content = "Como esperaba, hay un atajo... ¿Cómo lo encontraste?",
  ui_story_2002_3_26_dialog_content = "¿Quizás sea intuición de gato? Más importante, Líder, estoy tan conmovida con lo que dijiste, que me salvarías primero—",
  ui_story_2002_3_27_dialog_content = "No dije eso. Olvídalo. ¡Sigamos y preparémonos para pelear!",
  ui_story_2002_3_28_dialog_content = "Jeje, no puedes ser honesta contigo, miau.",
  ui_story_2002_3_29_dialog_content = "¡¿Eh?! ¡Este atajo está tan cerca de la Subciudad! ¡Parece una base secreta! Líder, ¿cavaste agujeros cuando eras una niña por cierto?\nPor ejemplo...",
  ui_story_2002_3_30_dialog_content = "¡Cállate! ¡Este no es un parque, así que mantén la guardia!",
  ui_story_2002_3_31_dialog_content = "¡Ah! Líder es muy estricta, miau.",
  ui_story_2002_3_32_dialog_content = "Hay menos enemigos de lo que esperaba. Debo haber matado a la mayoría ayer.",
  ui_story_2002_3_33_dialog_content = "¡Ah! Líder, ¡cuidado!",
  ui_story_2002_3_34_dialog_content = "!",
  ui_story_2002_3_35_dialog_content = "<color=#e8d9bb>Sharona blandeó su espada, cortando a su oponente en dos en el aire. Nunca tuvo oportunidad.</color>",
  ui_story_2002_3_36_dialog_content = "Hmph, ¿crees que no noté el ataque? Ya había sacado mi espada cuando estabas hablando, inútil...",
  ui_story_2002_3_37_dialog_content = "<color=#e8d9bb>Sharona volteó y se dio cuenta—que ese era solo uno de dos Eclipsites, y Philyshy había vencido al otro.</color>",
  ui_story_2002_3_38_dialog_content = "¡Por qué tú...!",
  ui_story_2002_3_39_dialog_content = "¿Oh? Líder, lo siento. Sabía que podías manejarlo todo, miau... Pero había uno más detrás de ti, así que te eché una mano.",
  ui_story_2002_3_40_dialog_content = "...No necesito tu ayuda. Solo necesitas protegerte a ti misma.",
  ui_story_2002_3_41_dialog_content = "Cuida de ti mismo, en lugar de a mi... ¡No quiero que me atrases!",
  ui_story_2002_3_42_dialog_content = "Pero... Ejem, gracias.",
  ui_story_2002_3_43_dialog_content = "(Me salvó, aunque casi la malinterpreté... Parece que no soy lo suficiente fuerte. Debo volverme lo suficiente fuerte para lidiar con todo yo sola...)",
  ui_story_2002_3_45_dialog_content = "Oh, em, no tengo otro propósito... Yo solo...",
  ui_story_2002_3_46_dialog_content = "Habla más bajo... Sigamos caminando.",
  ui_story_2002_3_47_dialog_content = "Ok—Philyshy está cansada y con sueño... Puedes ir más despacio...",
  ui_story_2002_4_1_dialog_content = "(Este atajo se extiende mucho, pero no parece llevar a ningún lado importante y no es conveniente para marchar. Me pregunto para qué se usa...)",
  ui_story_2002_4_2_dialog_content = "Oye, Philyshy, podríamos encontrarnos con enemigos fuertes pronto. Deberías tener cuidado y esconderte si puedes.",
  ui_story_2002_4_3_dialog_content = "Me temo que tu pequeño estoque no será suficiente para un choque frontal... ¿Oye, estás escuchando?",
  ui_story_2002_4_4_dialog_content = "Líder, lo siento... Estoy cansada... Tengo sueño, miau...",
  ui_story_2002_4_5_dialog_content = "¿Qué? ¿Somnolienta? ¡¿Ahora?! ¿Estas bromeando? ¡Despierta!",
  ui_story_2002_4_6_dialog_content = "Oh, pero tengo tanto sueño... Philyshy quiere una siesta. Que hay de una corta...",
  ui_story_2002_4_7_dialog_content = "¡¿Te parece este un lugar para dormir?! ¡No me atrases incluso si quieres morir! ¡No te protegeré!",
  ui_story_2002_4_8_dialog_content = "Me protegerás sí... Te ves feroz...",
  ui_story_2002_4_9_dialog_content = "Pero en realidad eres...muy... *roncando*",
  ui_story_2002_4_10_dialog_content = "¡No puedo creerlo...! ¿Acaso no dormiste por toda una noche? ¡¿Cómo puedes quedarte dormida así?!",
  ui_story_2002_4_11_dialog_content = "Vaya, realmente está dormida.",
  ui_story_2002_4_12_dialog_content = "\"El momento en que un compañero de equipo débil se descuida suele ser cuando el enemigo es más probable que se rompa.\"",
  ui_story_2002_4_13_dialog_content = "¡Graaaah...!",
  ui_story_2002_4_14_dialog_content = "Claro que lo sé. Sólo los bastardos patean a la gente cuando está en el suelo. Tócala bajo tu propio riesgo.",
  ui_story_2002_4_15_dialog_content = "Este nivel de batalla... ¿Solo juegas a la pelota? Qué coincidencia. Esto es en lo que soy mejor además de pelear.",
  ui_story_2002_4_16_dialog_content = "¡Oye, tú! ¿Por qué no has despertado aún?",
  ui_story_2002_4_17_dialog_content = "Urgh... ¿Cómo puede dormir tan profundo? Desde cuándo tiene Illumina un miembro como ella...",
  ui_story_2002_4_18_dialog_content = "(Tsk, la forma en cómo duerme me recuerda a algo... Me pregunto si mi Hermana Mayor me ve de la misma manera cuando duermo.)",
  ui_story_2002_4_19_dialog_content = "(¿Cómo se siente tan segura en dejar su seguridad en manos de otra persona? ¿Puede hacer esto por confianza...?)",
  ui_story_2002_4_20_dialog_content = "(Pero se sintió seguro en ese momento.)",
  ui_story_2002_4_21_dialog_content = "¡No, no soy igual que ella! ¡Levántate! ¡Ahora!",
  ui_story_2002_4_22_dialog_content = "...Yo...no puedo seguir... Tengo tanto sueño...",
  ui_story_2002_4_23_dialog_content = "¿Qué no dormiste suficiente anoche? Cielos... ¿Estas bromeando? ¡¿Estás dormida de nuevo?!",
  ui_story_2002_5_1_dialog_content = "Así que estamos aquí, tonta dragona.",
  ui_story_2002_5_2_dialog_content = "¿Hmm? ¿Despertaste?",
  ui_story_2002_5_3_dialog_content = "He estado velando por ti durante... Espera, ¿cómo me llamaste?",
  ui_story_2002_5_4_dialog_content = "¡Jajaja! ¡Parece que estás acostumbrada a que te llame así! ¿Me extrañas?",
  ui_story_2002_5_5_dialog_content = "¿Philyshy? Deja de jugar. ¿Estás aturdida por haber dormido demasiado? Ven aquí—",
  ui_story_2002_5_6_dialog_content = "¿Ya te olvidaste de mí? ¡Jajaja! Estoy feliz de conocerte por tercera vez, miau.",
  ui_story_2002_5_7_dialog_content = "¡¿Eres tú?! Suenas y hueles diferente... ¡¿Eres esa criatura?!",
  ui_story_2002_5_8_dialog_content = "¡Jeje, seguro te tardaste en darte cuenta! ¡Cómo se espera de alguien que está envejeciendo!",
  ui_story_2002_5_9_dialog_content = "<color=#e8d9bb>Los ojos de Sharona enfriaron mientras su mano instintivamente alcanzó la empuñadura de su espada. Esa persona en frente de ella ya no era Philyshy.\nEstaba segura de esto.</color>",
  ui_story_2002_5_10_dialog_content = "...¿quién eres? Si haces algo fuera de lugar, ¡no me culpes por atacarte!",
  ui_story_2002_5_11_dialog_content = "¿Por qué no adivinas?",
  ui_story_2002_5_12_dialog_content = "Eres el astuto demonio que quería matarme mientras dormía.",
  ui_story_2002_5_13_dialog_content = "¡Ajajajajajajaja! ¿Matarte? Solo estaba completando mi misión y quería tu cola en el camino. Por cierto, puedes llamarme Yumi.",
  ui_story_2002_5_14_dialog_content = "Por qué estás en el cuerpo de Philyshy... ¡Sal de ahí!",
  ui_story_2002_5_15_dialog_content = "¿Philyshy? ¿Qué? No estoy poseyendo el cuerpo de nadie o nada.",
  ui_story_2002_5_16_dialog_content = "Este cuerpo me pertenece en primer lugar.",
  ui_story_2002_5_17_dialog_content = "¿Ah? ¿Así que tu comportamiento habitual es sólo un disfraz? ¿Te escondiste en la oscuridad tanto tiempo, sólo para trabajar para los Eclipsites?",
  ui_story_2002_5_18_dialog_content = "¿Disfraz? ¡Jajajajaja! ¡No, no, no, no hay tal cosa, miau!",
  ui_story_2002_5_19_dialog_content = "¡Solo ve al grano y sé honesta conmigo! ¡No me culpes por ser despiadada si te atreves a jugar trucos conmigo!",
  ui_story_2002_5_20_dialog_content = "¿Despiadada? ¡Por qué no lo intentas entonces, tonta dragona!",
  ui_story_2002_5_21_dialog_content = "¡Jajaja! ¡Nada mal, tonta dragona! ¡Miau!",
  ui_story_2002_5_22_dialog_content = "Eres la única que queda. ¡No te escondas, sino le daré vuelta a este lugar para atraparte!",
  ui_story_2002_5_23_dialog_content = "¡Oh-no! ¡Deseo que llegue el momento! ¡Miau!",
  ui_story_2002_5_24_dialog_content = "Tsk...",
  ui_story_2002_5_25_dialog_content = "¿No vienes hacia mí?",
  ui_story_2002_5_26_dialog_content = "(Todo terminará una vez que acabe con ella. Ella ha causado un gran desastre...¡incluso me hizo quedar como tonta!)",
  ui_story_2002_5_27_dialog_content = "¿Estás cansada? ¿Quieres echar una siesta?",
  ui_story_2002_5_28_dialog_content = "Cállate...",
  ui_story_2002_5_29_dialog_content = "(Solo tomará un corte desde el hombro izquierdo hasta el abdomen derecho... Puedo someterla al instante desde esta distancia...)",
  ui_story_2002_5_30_dialog_content = "Las palabras y comportamiento de Philyshy me dan la sensación de que es dos personas separadas,",
  ui_story_2002_5_31_dialog_content = "pero eso no es todo. Ocasionalmente he notado que es capaz de comunicarse con los Eclipsites.",
  ui_story_2002_5_32_dialog_content = "Vivian, estás siendo muy sentimental sobre esto. Puede ser un simple defecto de personalidad. La gente dice que soy aterradora en batalla, también...",
  ui_story_2002_5_33_dialog_content = "También espero que sea solo un problema de personalidad, pero me temo que no es tan simple.",
  ui_story_2002_5_34_dialog_content = "¿Además, un Aurorian comunicándose con los Eclipsites? Eso es ridículo. Creí que había eliminado a todos ellos durante la guerra.",
  ui_story_2002_5_35_dialog_content = "Es cierto, Reinhardt me dijo en persona. Me temo que Philyshy hará algo que dañe a Illumina sin siquiera darse cuenta, lo que hará que se arrepienta de sus acciones.",
  ui_story_2002_5_36_dialog_content = "Bueno, si se atreve,",
  ui_story_2002_5_37_dialog_content = "Acabaré con ella sin pensarlo.",
  ui_story_2002_5_38_dialog_content = "(Pero por qué... ¿Por qué no me atrevo a golpearla?)",
  ui_story_2002_5_39_dialog_content = "(Por qué... Es tan simple como mover mi espada... ¡Diablos, solo hazlo, Sharona!)",
  ui_story_2002_5_40_dialog_content = "Líder, no estés enojada... ¡Te prometo que ayudaré! ¡Líder, te ves tan fuerte!\n¡Haré todo lo posible por igualarte!",
  ui_story_2002_5_41_dialog_content = "Me protegerás sí... Te vez feroz...pero en realidad eres...muy... *roncando*",
  ui_story_2002_5_42_dialog_content = "...*Resopla*...",
  ui_story_2002_5_43_dialog_content = "(Si Reinhardt arregló esto a propósito y sabe que no seré capaz de matarte... Qué se supone que haga...)",
  ui_story_2002_5_44_dialog_content = "...",
  ui_story_2002_5_45_dialog_content = "...¿Eh?",
  ui_story_2002_5_46_dialog_content = "“Cola”...",
  ui_story_2002_5_47_dialog_content = "¡Lo se!",
  ui_story_2002_5_48_dialog_content = "(Para realmente hacer algo así... ¡No! ¡Es solo una táctica! ¡Debo ejecutar lo que tenga que ejecutar!)",
  ui_story_2002_5_49_dialog_content = "<color=#e8d9bb>Sharona respiró profundamente y, de repente, lanzó su cola hacia el frente.</color>",
  ui_story_2002_5_50_dialog_content = "¿No querías mi cola? Vamos, ven atrápala. Atrápame y es tuya.",
  ui_story_2002_5_51_dialog_content = "¡Miau! ¡¡¡Q-qué!!!",
  ui_story_2002_5_52_dialog_content = "¡Mi ágil y divertida cola está frente a ti! ¡¿No la quieres?!",
  ui_story_2002_5_53_dialog_content = "(¡¿Cielos, qué hago?!)",
  ui_story_2002_5_54_dialog_content = "¡Rayos! ¡Cómo te atreves! ¡Tú en verdad—arghhh! ¡Miau!",
  ui_story_2002_5_55_dialog_content = "<color=#e8d9bb>Yumi saltó sobre la cola de Sharona, pero ésta se apartó ágilmente, moviendo su cola hacia el otro lado de su cuerpo mientras se balanceaba hacia su oponente.</color>",
  ui_story_2002_5_56_dialog_content = "Anzuelo, línea y plomada... ¡Por aquí!",
  ui_story_2002_5_57_dialog_content = "¡Te atrapé!",
  ui_story_2002_5_58_dialog_content = "¡¡¡¡¡¡Mrriiiauuuu!!!!!!",
  ui_story_2002_5_59_dialog_content = "Qué... Dónde estoy... ¿Ah? ¿Líder?",
  ui_story_2002_5_60_dialog_content = "Parece que has vuelto a la normalidad... Tonta gata, me hiciste perder mucho tiempo.",
  ui_story_2002_5_61_dialog_content = "¿Q-qué pasó justo ahora?",
  ui_story_2002_5_62_dialog_content = "...no pasó nada. No preguntes.",
  ui_story_2002_5_63_dialog_content = "¡¡¡Ah!!! ¡¡¡Oh, no!!! ¡¡¡Ahora recuerdo!!!",
  ui_story_2002_5_64_dialog_content = "...¡¿qué recordaste?! ¡¡No puedes decirle a nadie!!",
  ui_story_2002_5_65_dialog_content = "¿Ah? ¿Qué es? Acabo de recordar qué se perdió.",
  ui_story_2002_5_66_dialog_content = "¿Oh? Eh, bueno... ¿Qué era?",
  ui_story_2002_5_67_dialog_content = "No, para ser precisa, debería decir es lo que Yumi se llevó...",
  ui_story_2002_5_68_dialog_content = "¡Idiota! No me digas qué ya sabías... ¿Por nada no me dijiste? ¡¿No es un poco tarde para acordarse ahora?!",
  ui_story_2002_5_69_dialog_content = "¿Ah? Usualmente cambio con ella mientras duermo, y es fácil olvidarlo... Lo siento, miau...",
  ui_story_2002_5_70_dialog_content = "Recuerdo que era algo muy importante. Era dorado, brillante, como del tamaño de una palma. ¡Era muy poderoso!\n¡Es un tesoro que cuidamos mucho!",
  ui_story_2002_5_71_dialog_content = "Yumi se lo dio a alguien no se... No, nos conocíamos, pero no puedo decir quién era...\nParece un sueño que no puedo recordar...",
  ui_story_2002_5_72_dialog_content = "Olvídalo. Lo recuperaré pronto sin importar que era. Y tú, ¡más vale que te disculpes con lágrimas antes de que volvamos! De todas formas...\n¿Quién es Yumi?",
  ui_story_2002_5_73_dialog_content = "...Ella es mi gata. Antes era mi compañera, pero ahora es una segunda yo.",
  ui_story_2002_5_74_dialog_content = "Como viste por tu cuenta, no soy muy fuerte, pero me vuelvo más fuerte cuando estoy con Yumi.\nEso era cierto en el pasado e incluso ahora.",
  ui_story_2002_5_75_dialog_content = "Pero es muy probable que Yumi ya no está aquí. Quizás Yumi vive en el corazón de Philyshy como mis anhelos por ella.",
  ui_story_2002_5_76_dialog_content = "Quizás estos sentimientos son tan fuertes que a veces hago cosas extrañas... Tal vez deba ver un doctor.",
  ui_story_2002_5_77_dialog_content = "Después de esta misión, te diré todo sobre mi pasado, ¿está bien? ¡Tengo tantas historias interesantes que contar!",
  ui_story_2002_5_78_dialog_content = "Tu... Tu siempre eres tan difícil de entender. Como sea, ¿por qué me atacaste con el Eclipsite cuando estabas en ese estado?\nFue como si te pusiste en contra nuestra...",
  ui_story_2002_5_79_dialog_content = "Oh... Eso es serio... Lo siento que Yumi esté causándote problemas, Líder. Por favor perdónala.",
  ui_story_2002_5_80_dialog_content = "Yumi tampoco puede evitarlo... Es como si hubiera una voz en mi cabeza dándonos órdenes. Ahora que lo pienso, puede ser...",
  ui_story_2002_5_81_dialog_content = "...la voz malvada de una mujer.",
  ui_story_2002_6_1_dialog_content = "El atajo termina aquí. La persona que ha estado manipulándote seguro está detrás de esta puerta...",
  ui_story_2002_6_2_dialog_content = "¡Philyshy! ¿Cómo te sientes? ¿Por qué no me esperas aquí? Yo puedo—",
  ui_story_2002_6_3_dialog_content = "¡Oye! ¡No me mimes así! ¡Me he recuperado completamente!",
  ui_story_2002_6_4_dialog_content = "Eso es bueno. Cuando escapemos de aquí, necesito que me des una explicación más detallada... Tenemos cosas más importantes que hacer ahora.",
  ui_story_2002_6_5_dialog_content = "Líder, parece haber un aura extraña adentro...",
  ui_story_2002_6_6_dialog_content = "Es muy aparente. El hedor de Eclipsites es tan fuerte que me pone enferma.",
  ui_story_2002_6_7_dialog_content = "¡Enfócate! ¡Voy a abrir esta puerta!",
  ui_story_2002_6_8_dialog_content = "¡— Sí señor!",
  ui_story_2002_6_9_dialog_content = "¡Bienvenida al Instituto de las Grandes Armas, la mayor creación del maestro, el gran e inteligente Bowlinger con quien estás hablando!",
  ui_story_2002_6_10_dialog_content = "¿Qué puedo hacer por ti?",
  ui_story_2002_6_11_dialog_content = "¡Por favor muestra grandeza y muere de inmediato!",
  ui_story_2002_6_12_dialog_content = "Realmente no entiendo. Preferiría que me dijeras:",
  ui_story_2002_6_13_dialog_content = "“Bowlinger, ¿puedes matarme?”",
  ui_story_2002_6_14_dialog_content = "¡Ciertamente! ¡¡Prepararé un gran funeral para ti inmediatamente!!",
  ui_story_2002_6_15_dialog_content = "¡Oh! ¡Líder, ahora lo recuerdo!",
  ui_story_2002_6_16_dialog_content = "Parece que muchas personas están curiosas sobre qué es lo que recuerda la linda Philyshy. ¿Bien, y qué recordó Philyshy?",
  ui_story_2002_6_17_dialog_content = "Deja al increíble Bowlinger decirle a todos lo que Philyshy recuerda. Lo que Philyshy recuerda es en verdad una gran pregunta.",
  ui_story_2002_6_18_dialog_content = "Y eso es todo lo que Philyshy recuerda. Si están interesados en lo que Philyshy recuerda, también pueden—",
  ui_story_2002_6_19_dialog_content = "¡Cállate! ¡¡Quédate callado!!",
  ui_story_2002_6_20_dialog_content = "¡Esa cosa importante! ¡Fue entregada a esta... esta rata!",
  ui_story_2002_6_21_dialog_content = "Tu... Realmente sabes cómo ahorrarme tiempo.",
  ui_story_2002_6_22_dialog_content = "¿Rata? ¡Cómo te atreves a insultarme, al gran, cautivador Bowlinger!\n¡Te volaré en pedazos hasta que no seas más que un átomo!",
  ui_story_2002_6_23_dialog_content = "¡Ejem, ustedes son simplemente muy poderosas, y yo no puedo hacer más que admirarlas!",
  ui_story_2002_6_24_dialog_content = "¡Sin embargo, con la ayuda de la Srta. Philyshy, tengo la oportunidad de hacerles una importante pregunta! Srta. Sharona,",
  ui_story_2002_6_25_dialog_content = "¿Sabes qué es esto? ¡Oh! ¡El inteligente Bowlinger ha tomado la oportunidad de contestar esta pregunta! La respuesta es—¡el núcleo del nuevo sistema de energía de Illumina!\n¡¡Es un catalizador poderoso!!",
  ui_story_2002_6_26_dialog_content = "¡¡Si lo uso, toda Illumina, ni hablemos de ustedes dos, volará en pedazos!!",
  ui_story_2002_6_27_dialog_content = "¡Originalmente, el maestro quería que cavara un túnel debajo de la Subciudad y colocara suficiente pólvora para destruir sus cimientos en preparación para el día en que ataque a Illumina!",
  ui_story_2002_6_28_dialog_content = "Inesperadamente, encontré un percance en mi investigación. ¡Casi no pude desarrollar mi arma definitiva para perforar el sistema de defensa de Gannon!",
  ui_story_2002_6_29_dialog_content = "¡Jeje! ¡Pero gracias a usted, Srta. Philyshy, finalmente pude! ¡Su persona Yumi me trajo el catalizador que necesitaba!",
  ui_story_2002_6_30_dialog_content = "...esto...",
  ui_story_2002_6_31_dialog_content = "\"Darkflow fue utilizado para modificar a Yumi y realizar experimentos para fusionarla con Philyshy. En terapia de trauma psicológico.\"",
  ui_story_2002_6_32_dialog_content = "“...tomamos ventaja de la débil voluntad de los animales para manipular a Philyshy. Más observación es requerida... Riesgo: Alto.”",
  ui_story_2002_6_33_dialog_content = "¡Un plan tan ingenioso solamente puede ser ideado por el gran —Ejem! ¡¡Casi lo suelto todo en mi emoción!!",
  ui_story_2002_6_34_dialog_content = "Lo siento, líder... Yo...",
  ui_story_2002_6_35_dialog_content = "Cállate. No puedo controlar mi ira ahora mismo—",
  ui_story_2002_6_36_dialog_content = "Todo es culpa de Philyshy. Es porque yo—",
  ui_story_2002_6_37_dialog_content = "¡Escoria! ¡Cómo te atreves a usar a mi amiga así!",
  ui_story_2002_6_38_dialog_content = "¿Ah? ¿Ah? ¿A-amiga?",
  ui_story_2002_6_39_dialog_content = "¡Sí, son grande amigas! ¡También podría matar a todos tus otros amigos de Illumina luego de deshacerme de ustedes!",
  ui_story_2002_6_40_dialog_content = "Ya que ustedes dos ratones afortunados han descubierto el plan del maestro antes de tiempo, ¡tal vez debería destruir a Gannon antes y ofrecerlo al maestro antes!",
  ui_story_2002_6_41_dialog_content = "<color=#e8d9bb>Bowlinger introdujo rápidamente el dispositivo dorado que le había pasado Yumi en la base del reactor y encendió la energía.</color>",
  ui_story_2002_6_44_dialog_content = "¡El núcleo ha sido insertado! ¡Mi inmensamente poderoso dispositivo ha sido activado! ¡Vean su color único y su delicada figura!",
  ui_story_2002_6_45_dialog_content = "¡Se ve tan impresionante y tiene una textura tan maravillosa!",
  ui_story_2002_6_46_dialog_content = "También tiene este...este...¿este olor seductor...?",
  ui_story_2002_6_47_dialog_content = "¿Por qué me impides atacarlo? ¿Crees que debemos quedarnos aquí y esperar a que nos mate, Philyshy?",
  ui_story_2002_6_48_dialog_content = "¡No! ¿Puedes olerlo, Líder?",
  ui_story_2002_6_49_dialog_content = "...Parece oler a... Ejem... putrefacción... ¿Tan mal huele el núcleo energético?",
  ui_story_2002_6_50_dialog_content = "Esto es... ¿Ah? ¿Pescado enlatado?",
  ui_story_2002_6_51_dialog_content = "Oh... Ahora recuerdo—Yumi parecía haberse llevado una lata de pescado.",
  ui_story_2002_6_52_dialog_content = "...entonces, lo realmente importante que dijiste antes... ¿es pescado enlatado?",
  ui_story_2002_6_53_dialog_content = "¡No es cualquier pescado enlatado! ¡Reinhardt lo trajo desde Northland! ¡Es una lata de arenque súper rara!",
  ui_story_2002_6_54_dialog_content = "Okey, okey, entiendo... Veo que eres una gata.",
  ui_story_2002_6_55_dialog_content = "Líder, ¿puedes devolverme la lata? Le diré a Yumi que deje de intentar robarte la cola todo el tiempo.",
  ui_story_2002_6_56_dialog_content = "¡¡¡¿P-p-pescado enlatado?!!! ¡Mentirosa! ¡Bah! ¡Urgh! ¡¡Cómo te atreves!!",
  ui_story_2002_6_57_dialog_content = "¡¡Cómo te atreves burlarte así de mí!! Tú... urgh... ¡estás condenada! ¡¡¡Cómo es posible que huela tan mal!!!",
  ui_story_2002_6_58_dialog_content = "¡Incluso si el núcleo es falso, el plan aún no es una completo fracaso!\n¡Al menos volaré este lugar en pedazos! ¡¡Mueran!!",
  ui_story_2002_6_59_dialog_content = "¡Activaré las instrucciones de autodestrucción! ¡¡Inicia la cuenta de 10 segundos!!",
  ui_story_2002_6_60_dialog_content = "¡¡Corre, Líder!!",
  ui_story_2002_6_61_dialog_content = "¿Cuál es la prisa? ¿Qué no dijo que teníamos 10 segundos?",
  ui_story_2002_6_62_dialog_content = "¡Rápido!",
  ui_story_2002_6_63_dialog_content = "<color=#e8d9bb>6—5—</color>",
  ui_story_2002_6_64_dialog_content = "Estoy buscando tu lata... ¡Deja de gritar! Urgh... ¡¡Este olor!!",
  ui_story_2002_6_65_dialog_content = "<color=#e8d9bb>4—</color",
  ui_story_2002_6_66_dialog_content = "Entendido. Dame tu mano. ¡Nos vamos!",
  ui_story_2002_6_67_dialog_content = "<color=#e8d9bb>3—2—</color>",
  ui_story_2002_6_68_dialog_content = "¡Ah! ¡Me caigo!",
  ui_story_2002_6_69_dialog_content = "¡¡Cielos, eres un dolor, pequeña gatita!!",
  ui_story_2002_6_70_dialog_content = "<color=#e8d9bb>¡1—!</color>",
  ui_story_2002_6_71_dialog_content = "<color=#e8d9bb>Al final del atajo, un destello brillante y una ráfaga de aire las alcanzó inmediatamente, seguido de un estruendo ensordecedor.</color>",
  ui_story_2002_6_73_dialog_content = "...Lo siento... Todo esto es mi culpa...",
  ui_story_2002_6_74_dialog_content = "¡Era un factor de riesgo para empezar, y algo malo en verdad pasó! ¡Boo-hoo! ¡Incluso la piel de mi cola se ha encrespado por el calor!",
  ui_story_2002_6_75_dialog_content = "¡Este no es el momento para tus tonterías, idiota! ¡Mi cola se está quemando, también!",
  ui_story_2002_6_76_dialog_content = "...¡sin importar qué, si de verdad de preocupas por tu problema, encontraré una forma de curarte! ¡Di esas cosas otra vez y te abofetearé tu cabecita de gatita con el lado plano de mi espada!",
  ui_story_2002_6_77_dialog_content = "¡Lo siento! Empiezo a tener sueño de nuevo... Líder, quiero dormir... Puedo...tomar una...",
  ui_story_2002_6_79_dialog_content = "¡Te va a dormir incluso si te lo prohíbo! ¡Solo haz lo que quieras!",
  ui_story_2002_6_X1_dialog_content = "Aún te protegeré esta vez...",
  ui_story_2002_6_80_dialog_content = "<color=#e8d9bb>Tras la extinción del fuego, una misteriosa figura apareció entre las ruinas de la zona central de la explosión.</color>",
  ui_story_2002_6_81_dialog_content = "¿Bowlinger? ¿Es esta miserable situación el infalible \"plan perfecto\" que me prometiste antes?",
  ui_story_2002_6_82_dialog_content = "<color=#e8d9bb>Mientras tanto, el moribundo Bowlinger yacía inerte en las ruinas, incapaz de completar los saludos.</color>",
  ui_story_2002_6_83_dialog_content = "“El objeto” era pescado enlatado... Los gatos son muy impredecibles, no debería haber esperado mucho de ellos.",
  ui_story_2002_6_84_dialog_content = "Schummer es mucho más confiable. Por supuesto, es demasiado apresurado intentar destruir la sede de Illumina...\nAl menos hicimos el intento.",
  ui_story_2002_6_85_dialog_content = "Bowlinger.",
  ui_story_2002_6_86_dialog_content = "...Sí... ejem...",
  ui_story_2002_6_87_dialog_content = "Eres incluso más inútil que una gata.",
  ui_story_2002_6_88_dialog_content = "Pero todo se ha esfumado gracias a ti. Supongo que nadie sabe de este... calvario.",
  ui_story_2002_6_89_dialog_content = "Maestro, yo... yo...",
  ui_story_2002_6_90_dialog_content = "No necesitas culparte. Hay incontables seguidores en Eclipse y tus otros compatriotas cumplirán tus ambiciones en tu lugar.",
  ui_story_2002_6_91_dialog_content = "Mientras tanto, tú y la gata son simples fracasos.",
  ui_story_2002_6_92_dialog_content = "...",
  ui_story_2002_6_93_dialog_content = "¡Ah! Se siente bien regresar a Illumina, aunque no puedo quedarme por mucho tiempo. ¿Me pregunto cómo estará <color=#FFB400>mi vieja amiga</color> ahora?",
  ui_story_2002_6_94_dialog_content = "¿Quizás esté comandando a algunos soldados desde su elevada posición? ¿O quizás esté acurrucada en su hogar, satisfecha con el estatus quo...?",
  ui_story_2002_6_95_dialog_content = "R-Reinhardt...simplemente no es rival para ti, mi maestro... ¡Ejem!",
  ui_story_2002_6_96_dialog_content = "No necesito que me digas eso. Mi odio se cocina a fuego lento, pero hará un sonido ensordecedor cuando mi plan se haga realidad. Ella lo oirá de una forma u otra algún día.",
  ui_story_2002_6_97_dialog_content = "En cuanto a ti... Cierra tus ojos. Te libraré de tu miseria. El sol ha muerto—",
  ui_story_2002_6_98_dialog_content = "<color=#e8d9bb>Los ojos de Bowlinger perdieron su último brillo de luz cuando levantó la cabeza en señal de alivio, y pronunció sus últimas palabras—</color>",
  ui_story_2002_6_99_dialog_content = "—Eclipse existirá por toda la eternidad...",
  ui_story_2003_1_1_dialog_content = "Desde que vi ese magnífico palacio blanco, supe que era ahí donde pertenecía. Ese era mi <color=#FFB400>hogar</color>...",
  ui_story_2003_1_2_dialog_content = "No esta <color=#FFB400>Umbraton</color> sucia en ruinas . Haré lo que sea para...",
  ui_story_2003_1_3_dialog_content = "Miau... miau...",
  ui_story_2003_1_4_dialog_content = "¡Oh! ¡Ay!",
  ui_story_2003_1_5_dialog_content = "¡Cuidado, Connolly!",
  ui_story_2003_1_6_dialog_content = "Me caí accidentalmente de nuevo... ¡Qué torpe soy!",
  ui_story_2003_1_7_dialog_content = "<color=#e8d9bb>Era una tarde de verano. Connolly y su amigo de Clarinete estaban limpiando el sótano del café Holiday.</color>",
  ui_story_2003_1_8_dialog_content = "<color=#e8d9bb>En este pequeño, polvoso cuarto se escondía el pasado de Connolly</color>",
  ui_story_2003_1_9_dialog_content = "Son todas las hojas de música que trajimos cuando nos mudamos. Déjame ver...",
  ui_story_2003_1_10_dialog_content = "¡Recuerdo esta! —Baile en Mi-mayor— por Clarkson... Este es —Himno al Viento—... y este es — Litman Polka—.",
  ui_story_2003_1_11_dialog_content = "¿Y qué no es esta la —Variante de Noche Blanca—? Los nobles aman estas cosas, una especie de melodías corales con muchos acordes.",
  ui_story_2003_1_12_dialog_content = "Se llama solemnidad.",
  ui_story_2003_1_13_dialog_content = "¿Por qué peleas? Cuidado, tiene polvo ya que no se ha limpiado durante años.",
  ui_story_2003_1_14_dialog_content = "Oh, y este es...",
  ui_story_2003_1_15_dialog_content = "<color=#e8d9bb>Anton le entregó una sola hoja de música con la cubierta amarillenta, con una sola palabra \"Hogar\" en su esquina inferior derecha.</color>",
  ui_story_2003_1_X15_dialog_content = "“El único lugar donde podemos ocultar todos nuestros fracasos y debilidades, un lugar de dulce amor.\"",
  ui_story_2003_1_X16_dialog_content = "<color=#FFB400>\"Hogar\"</color>, un palacio de amor, alegría y sonrisas... ¡Qué bonito!",
  ui_story_2003_1_16_dialog_content = "Connolly, ¿por qué no dejas que mamá te enseñe como tocarla?",
  ui_story_2003_1_17_dialog_content = "Oh, esto... Creí haberlo perdido hace mucho. Fue la primera pieza que mi madre me enseñó a tocar.",
  ui_story_2003_1_18_dialog_content = "*Tarareando suavemente*",
  ui_story_2003_1_19_dialog_content = "...¿Has conseguido afinar una sola nota?",
  ui_story_2003_1_20_dialog_content = "¡La emoción es clave aquí! ¡Mi sincera y apasionada emoción!",
  ui_story_2003_1_21_dialog_content = "Pero nunca te he escuchado tocar esta pieza. ¿Olvidaste cómo hacerlo? ¿Necesitas mirar la hoja?",
  ui_story_2003_1_22_dialog_content = "No, no sé, es sólo que...",
  ui_story_2003_1_23_dialog_content = "No siento que estoy en posición para tocarla aún. Después de todo, se llama <color=#FFB400>\"Hogar\"</color>...",
  ui_story_2003_1_24_dialog_content = "¿<color=#FFB400>Hogar</color>?",
  ui_story_2003_1_25_dialog_content = "¿Será que extrañas esa gran casa blanca?",
  ui_story_2003_1_26_dialog_content = "¿Ese viejo hogar?...",
  ui_story_2003_1_27_dialog_content = "Prefiero el Café Holiday. Tienen bastante comida decente y bebidas... Y mucha gente extraña, también...",
  ui_story_2003_1_28_dialog_content = "Perdón por interrumpir. Connolly, escuché un llamado de ayuda.",
  ui_story_2003_1_29_dialog_content = "¿Un llamado de ayuda?",
  ui_story_2003_1_30_dialog_content = "Sí, se enciende y apaga, y muy débil, como una llama muriendo...",
  ui_story_2003_1_31_dialog_content = "¡No puedo ignorarlo! ¡No debo... tener miedo! ¡Vamos, Anton!",
  ui_story_2003_1_32_dialog_content = "¿No deberíamos preguntarle a Dayna o Robyn antes? ¿Y si nos encontramos con una banda de Eclipsites? ¡Boo-hoo, eso sería aterrador!",
  ui_story_2003_1_33_dialog_content = "Dejémoslas solas. Tienen su propio trabajo...",
  ui_story_2003_1_34_dialog_content = "Creo que podemos hacerlo por nuestra cuenta.",
  ui_story_2003_1_35_dialog_content = "¡Gaah!",
  ui_story_2003_1_36_dialog_content = "*Tocando el clarinete*",
  ui_story_2003_1_37_dialog_content = "¡Connolly! ¡Te estás haciendo muy buena en eso!",
  ui_story_2003_1_38_dialog_content = "Después de todo, así es como es la vida en Umbraton.",
  ui_story_2003_1_39_dialog_content = "No hay barrera en el cielo y los Eclipsites pueden estar acechando cualquier lugar.",
  ui_story_2003_1_40_dialog_content = "Me sentí algo débil antes. Pero parece que me estoy haciendo más fuerte ahora.",
  ui_story_2003_1_41_dialog_content = "¡Ahh! ¡Un Dretcher!",
  ui_story_2003_1_42_dialog_content = "<size=45>¡Eeeek! </size>",
  ui_story_2003_1_43_dialog_content = "¡¿D-dónde está?!",
  ui_story_2003_1_44_dialog_content = "¡Oye, solo bromeaba!",
  ui_story_2003_1_45_dialog_content = "¡Ay! ¡Cuidado de no golpear mis tentáculos!",
  ui_story_2003_1_46_dialog_content = "No molestes a Connolly. Sabes, somos “hermanos” pero a veces eres muy molesto.",
  ui_story_2003_1_47_dialog_content = "Entonces... ¿Está aquí? Está muy oscuro. No esperaba ver callejones tan oscuros en Umbraton.",
  ui_story_2003_1_48_dialog_content = "Sí, puedo oírlo muy claro. El llamado de ayuda era muy distinto ahora.",
  ui_story_2003_1_49_dialog_content = "Pero esto parece un montón de cajas viejas...",
  ui_story_2003_1_50_dialog_content = "¡A-achuu! Tanto polvo... ¿Realmente hay alguien aquí?",
  ui_story_2003_1_51_dialog_content = "Como sea, quitemos estas cajas del camino y veamos que hay ahí abajo.",
  ui_story_2003_1_52_dialog_content = "Miau...",
  ui_story_2003_1_53_dialog_content = "Shhh... ¿Escuchaste eso? Hay algo ahí.",
  ui_story_2003_1_54_dialog_content = "¿Qué hay debajo de esas cajas?...",
  ui_story_2003_1_55_dialog_content = "Señor, ¿está bien? ¡No te preocupes! Lo sacaremos en un segundo... Oye...",
  ui_story_2003_1_56_dialog_content = "Miau... miau...",
  ui_story_2003_1_57_dialog_content = "Entiendo...",
  ui_story_2003_1_58_dialog_content = "¿Un <color=#FFB400>Gato</color>?",
  ui_story_2003_2_1_dialog_content = "Puede que el Gremio de Explorador Nublar no se dedique a la caridad, pero esas prácticas deshonestas podrían empañar nuestra reputación.",
  ui_story_2003_2_2_dialog_content = "Qué astuta rata. Dayna, Robyn, agarren la cola y arránquenla.",
  ui_story_2003_2_3_dialog_content = "¡Rayos, Robyn! ¡Rodéalo!",
  ui_story_2003_2_4_dialog_content = "Esta rata se atreve a correr en nuestro territorio... Debemos atraparlo hoy.",
  ui_story_2003_2_5_dialog_content = "*Asiente*",
  ui_story_2003_2_6_dialog_content = "¡No puedo creer mis ojos! ¿Está desviándose? ¡Cómo corre!",
  ui_story_2003_2_7_dialog_content = "Cuando lo atrape, haré que se arrodille y ruegue por piedad...",
  ui_story_2003_2_8_dialog_content = "¡O quizás una buena paliza será mejor!",
  ui_story_2003_2_9_dialog_content = "*Sopla... Resopla...* Eh... ¡Qué molestia!",
  ui_story_2003_2_10_dialog_content = "¡Robyn, a tu izquierda!",
  ui_story_2003_2_11_dialog_content = "¡Espera, no hay salida! Cómo...",
  ui_story_2003_2_12_dialog_content = "...Solo desapareció.",
  ui_story_2003_2_13_dialog_content = "¡Gahhhh!",
  ui_story_2003_2_14_dialog_content = "Tantas escorias amables fueron reunidas y atrapadas...",
  ui_story_2003_2_15_dialog_content = "¡Oye!",
  ui_story_2003_2_16_dialog_content = "*Cortando con espada*",
  ui_story_2003_2_17_dialog_content = "¡Rayos! Estuvimos en persecución por tanto tiempo, y para nada... Ya puedo oír al jefe burlándose.",
  ui_story_2003_2_18_dialog_content = "Y estoy segura que no obtendremos nuestro salario ahora. De alguna forma duele mi cráneo ahora mismo...",
  ui_story_2003_2_19_dialog_content = "Una cosa es cierta... Ese tipo no es un empresario común.",
  ui_story_2003_2_20_dialog_content = "Café...",
  ui_story_2003_2_21_dialog_content = "Tenemos que seguir, aún si el trabajo no ha terminado.",
  ui_story_2003_2_22_dialog_content = "Vamos tener una taza en el Café de Connolly y descansar.",
  ui_story_2003_2_23_dialog_content = "Tomen, espresso y leche fresca por su arduo trabajo, chicas.",
  ui_story_2003_2_24_dialog_content = "¡Mmm! Tu café es de fuera de este mundo, Connolly. Ahora estoy en un dilema, porque quiero que vuelvas a trabajar en el Gremio, pero al mismo tiempo, no puedo separarme de este café...",
  ui_story_2003_2_25_dialog_content = "Así que esa persona era...",
  ui_story_2003_2_26_dialog_content = "Era un mercante certificado del Gremio Explorador Nublar. Hemos estado siguiéndolo por mucho tiempo. ¿Has escuchado del <color=#FFB400>extracto de oro blanco</color>?",
  ui_story_2003_2_27_dialog_content = "¿<color=#FFB400>Extracto de oro blanco</color>...?",
  ui_story_2003_2_28_dialog_content = "Un tipo de líquido blanco, con cubos dorados y transparentes adentro, parecida a la gelatina en la leche.",
  ui_story_2003_2_29_dialog_content = "Se dice que permite <color=#FFB400>la limpieza de las líneas de sangre, llevando a la gente a Lumopolis</color>.",
  ui_story_2003_2_30_dialog_content = "Es algo difícil de creer.",
  ui_story_2003_2_31_dialog_content = "¿Verdad? Pero para aquellos que han pasado toda su vida en Umbraton, viajar a Lumopolis es algo más que solo subirse a bordo de un dirigible en la terminal.",
  ui_story_2003_2_32_dialog_content = "Pare ellos, son dos mundos completamente diferentes.",
  ui_story_2003_2_33_dialog_content = "Mmm...",
  ui_story_2003_2_34_dialog_content = "Puede proveer una sensación de placer, similar a poder inagotable. Pero al mismo tiempo, quienes tomen el extracto se convertirán en tarros de miel para Eclipsites,",
  ui_story_2003_2_35_dialog_content = "<size=45>eventualmente terminan como sus presas</size>.",
  ui_story_2003_2_36_dialog_content = "Sin embargo, aún hay muchos quienes no creen en los efectos secundarios del extracto de oro blanco, persiguiéndolo fanáticamente.",
  ui_story_2003_2_37_dialog_content = "El tipo que vende esta cosa no tiene consideración alguna por el gremio.",
  ui_story_2003_2_38_dialog_content = "...Habrán nuevas víctimas.",
  ui_story_2003_2_39_dialog_content = "Sí...",
  ui_story_2003_2_40_dialog_content = "Oh, no tenemos café.",
  ui_story_2003_2_41_dialog_content = "Descuiden, les traeré más.",
  ui_story_2003_2_42_dialog_content = "Gracias... Es muy amable de ti, Connolly.",
  ui_story_2003_2_43_dialog_content = "Oh sí, quería preguntar desde que entré. ¿Qué hay en la mesa?",
  ui_story_2003_2_44_dialog_content = "Es... Erm... Es un gato robótico.",
  ui_story_2003_2_45_dialog_content = "<color=#e8d9bb>Connolly describió lo sucedido con Dayna y Robyn.</color>",
  ui_story_2003_2_46_dialog_content = "Oh... Es un robot. Eso es algo inusual. ¿Se mueve?",
  ui_story_2003_2_47_dialog_content = "No, un minuto... ¿Así que quieres destruir a los Eclipsites? ¿Por qué no nos dijiste? ¿Y si terminas en una situación peligrosa?",
  ui_story_2003_2_48_dialog_content = "Como siempre, yendo sola. Todos esos Eclipsites... Tu...",
  ui_story_2003_2_49_dialog_content = "Dayna...",
  ui_story_2003_2_50_dialog_content = "Okey, okey, me callaré... ¡Pero avísanos la próxima vez! ¡Después de todo, somos tu <color=#FFB400>familia</color>!",
  ui_story_2003_2_51_dialog_content = "...De acuerdo, depende de ti.",
  ui_story_2003_2_52_dialog_content = "Ahora cuéntanos más sobre el gatito. ¿Qué hace?",
  ui_story_2003_2_53_dialog_content = "Cuando lo encontré hacía algunos ruidos, pero ahora está completamente fijo y silencioso. ¿Quizás está...roto?",
  ui_story_2003_2_54_dialog_content = "Lo tengo. En esto soy buena.",
  ui_story_2003_2_55_dialog_content = "¡Dime que no serás violenta!",
  ui_story_2003_2_56_dialog_content = "Zzzzsshhh... ¡Miau! ¡Miau!",
  ui_story_2003_2_57_dialog_content = "¡Wow, lo arreglaste!",
  ui_story_2003_2_58_dialog_content = "¿Qué dije?",
  ui_story_2003_2_59_dialog_content = "También se lame y se frota contra las piernas. Oh, hora de unas caricias...",
  ui_story_2003_2_60_dialog_content = "¡Te encontré! Dayna y Robyn... ¿Volvieron a escaparse del Café Holiday en horas de trabajo?\n¡Tendré que descontarlo de su salario!",
  ui_story_2003_2_61_dialog_content = "Rayos, el deber llama. Hasta la próxima entonces.",
  ui_story_2003_2_62_dialog_content = "...Adiós, Connolly.",
  ui_story_2003_2_63_dialog_content = "Oh, sí, y no le agregues azúcar al espresso la próxima vez.",
  ui_story_2003_2_64_dialog_content = "Parece que estamos solos de nuevo.",
  ui_story_2003_2_65_dialog_content = "Sí, pero tenemos al gatito.",
  ui_story_2003_2_66_dialog_content = "El gatito... Ey, ¿dónde está?",
  ui_story_2003_2_67_dialog_content = "<color=#e8d9bb>La puerta del café se movió un poco. Esa silenciosa cinturita se escabulló sin ser notada.</color>",
  ui_story_2003_3_1_dialog_content = "¿A dónde fue?",
  ui_story_2003_3_2_dialog_content = "Descuida, Connolly. Ya puedo olerlo.",
  ui_story_2003_3_3_dialog_content = "Es el... ¿Centro de lanzadera? ¡Está justo ahí!",
  ui_story_2003_3_4_dialog_content = "¿Civiles de Umbraton? ¿Y del bloque más sucio? Ni siquiera tienes un pase.",
  ui_story_2003_3_5_dialog_content = "¡No soy uno de los nobles, pero he trabajado para ellos! Tengo todas las cualidades necesarias, por favor déjeme entrar a Lumopolis, señor.",
  ui_story_2003_3_6_dialog_content = "Basta. Vete, por favor. No obstruyas los deberes oficiales.",
  ui_story_2003_3_7_dialog_content = "Sin prisa. Tu allá... Por favor dinos más de tus cualidades.",
  ui_story_2003_3_8_dialog_content = "Mi nombre es Krane y soy un mecánico especializándome en...estudiar la tecnología Lumina de civilizaciones antiguas.",
  ui_story_2003_3_9_dialog_content = "¡Debes haber oído sobre mí! ¡He estado en Lumopolis y he hecho algunos productos mecánicos para la familia Troy! Solo mira este reloj.",
  ui_story_2003_3_10_dialog_content = "Oh, es bastante bonito.",
  ui_story_2003_3_11_dialog_content = "Así que...",
  ui_story_2003_3_12_dialog_content = "Pero Lumopolis no necesita esos artefactos inútiles.",
  ui_story_2003_3_13_dialog_content = "Krane, claro, hemos oído este nombre... El talentoso mecánico que dice haber dominado la tecnología de las civilizaciones antiguas... no es más que un aficionado.",
  ui_story_2003_3_14_dialog_content = "¿Creaste un gato cantante y lo trajiste a los Nobles, cierto? Como sea, el gato resultó ser mudo. Después de eso, tú y tu gato fueron desterrados de Lumopolis.",
  ui_story_2003_3_15_dialog_content = "¿Será este gato?",
  ui_story_2003_3_16_dialog_content = "<color=#e8d9bb>Un gatito negro apareció de repente a los pies del mecánico, sentado obedientemente y mirando con sus grandes ojos.</color>",
  ui_story_2003_3_17_dialog_content = "Pero, señor... T-también puedo demostrar otras habilidades. Solamente... no puedo pensar en nada ahora... Diablos...",
  ui_story_2003_3_18_dialog_content = "Como sea, haré lo mejor para tener un trabajo en Lumopolis.",
  ui_story_2003_3_19_dialog_content = "Vete de aquí. Desperdiciaste mucho nuestro tiempo.",
  ui_story_2003_3_20_dialog_content = "Miau...",
  ui_story_2003_3_21_dialog_content = "¡¿Qué le pasa a este Gato?!",
  ui_story_2003_3_22_dialog_content = "¡Atrápalo! Atacó con furia a los guardias. ¡Debemos llevarlo al salón de Justicia!",
  ui_story_2003_3_23_dialog_content = "Por favor... Señor... No...",
  ui_story_2003_3_24_dialog_content = "¡Anton!",
  ui_story_2003_3_X24_dialog_content = "¡Whoa! ¡Guardias Lumo buscando pelear!",
  ui_story_2003_3_25_dialog_content = "Pero está bien. Connolly, vamos a dormirlos ahora.",
  ui_story_2003_3_26_dialog_content = "Al fin... ¡Es seguro! Descuida, N-no los lastimé. Solo les desee dulces sueños.",
  ui_story_2003_3_27_dialog_content = "...",
  ui_story_2003_3_28_dialog_content = "¿Estás bien?",
  ui_story_2003_3_29_dialog_content = "¡Casi tuve la oportunidad de regresar a Lumopolis, pero llegaron ustedes y lo arruinaron!",
  ui_story_2003_3_30_dialog_content = "Miau... miau...",
  ui_story_2003_3_31_dialog_content = "¿Tú de nuevo? Creí que estabas roto...",
  ui_story_2003_3_32_dialog_content = "¿Por qué me sigues? No estaría en Umbraton si no fuera por ti, pedazo de...\nYa era un invitado de los Nobles...",
  ui_story_2003_3_33_dialog_content = "<size=45>Lárgate de mi vista... ¡Ahora!</size>",
  ui_story_2003_3_34_dialog_content = "Ah, tu...",
  ui_story_2003_3_35_dialog_content = "Se escapó...",
  ui_story_2003_3_36_dialog_content = "¿Qué le pasa a ese tipo? Lo ayudamos, pero no solo no lo apreció, incluso dejó esta pobre cosita aquí.",
  ui_story_2003_3_37_dialog_content = "Gatito... ¿No lo estás siguiendo?",
  ui_story_2003_3_38_dialog_content = "Papá... ¿Mamá? ¿A dónde van?",
  ui_story_2003_3_39_dialog_content = "¿Connolly, nos esperarías aquí?",
  ui_story_2003_3_X39_dialog_content = "Pronto regresaremos a Lumopolis, nuestro hogar real.",
  ui_story_2003_3_X40_dialog_content = "Puedes sentirte muy sola...",
  ui_story_2003_3_X41_dialog_content = "Aquí, toma mi clarinete... Debería confortarte un poco.",
  ui_story_2003_3_X42_dialog_content = "Es como antes...",
  ui_story_2003_3_40_dialog_content = "Se dejó de mover, Connolly...",
  ui_story_2003_3_41_dialog_content = "... Está sin Lumina...",
  ui_story_2003_3_42_dialog_content = "Hoy no es mi día... Por qué... ¿Por qué...?",
  ui_story_2003_3_43_dialog_content = "No hay nada más que dilapidación y oscuridad. Luchando con comida barata y arruinada, viviendo en pobreza interminable.",
  ui_story_2003_3_44_dialog_content = "No lo soporto más. Odio este lugar. Me he quedado sin ningún tipo de satisfacción... ¡¡¡Solo quiero ir a mi <color=#FFB400>hogar</color>!!!",
  ui_story_2003_3_45_dialog_content = "¿Quieres ir a Lumopolis?",
  ui_story_2003_3_46_dialog_content = "¡¿Quién...quién fue?!",
  ui_story_2003_3_47_dialog_content = "¿No lo entiendes?",
  ui_story_2003_3_48_dialog_content = "Esos trucos solamente pueden hacer que pongas pie en Lumopolis, pero nunca harán que cruces la barrera de línea de sangre. Para quedarte aquí, necesitas sangre Noble, la cual no tienes.",
  ui_story_2003_3_49_dialog_content = "Pero, ¿qué puedo hacer? Soy inferior por naturaleza... ¿Significa que tendré que quedarme en este basurero por siempre?",
  ui_story_2003_3_50_dialog_content = "¿Por qué no intentas algo más?",
  ui_story_2003_3_51_dialog_content = "Toma esto, y purificará tu sangre de toda la suciedad—entonces serás capaz de unirte a la sociedad de Lumopolis.",
  ui_story_2003_3_52_dialog_content = "Inténtalo.",
  ui_story_2003_4_1_dialog_content = "Así que, ya estaba roto antes... Luego fue golpeado por Dayna, pateado por el guardia, y arrojado a un lado por su dueño.",
  ui_story_2003_4_2_dialog_content = "¡Es un milagro que no se hizo pedazos!",
  ui_story_2003_4_3_dialog_content = "Sí... En efecto.",
  ui_story_2003_4_4_dialog_content = "Si solo le diera un buen uso a este don, sin duda podría ganar mucho dinero. Es una pena que...",
  ui_story_2003_4_5_dialog_content = "Hay muchas personas con sueños poco realistas que desean llegar a los palacios blancos de Lumopolis.",
  ui_story_2003_4_6_dialog_content = "He oído que las pobres almas intentando colarse en Lumopolis a través del Centro fueron empujadas a medio camino y acabaron incapacitadas.",
  ui_story_2003_4_7_dialog_content = "Los que se acerquen demasiado al sol morirán quemados... ¿Entiendo que has vivido en Lumopolis, verdad?",
  ui_story_2003_4_8_dialog_content = "Era muy joven entonces...y no me gustó ahí...",
  ui_story_2003_4_9_dialog_content = "Connolly...",
  ui_story_2003_4_10_dialog_content = "*Moviendo su cabeza*",
  ui_story_2003_4_11_dialog_content = "Un poco más y... ¡Listo! Es todo lo que puedo hacer.",
  ui_story_2003_4_12_dialog_content = "No, está genial. ¡Muchas gracias!",
  ui_story_2003_4_13_dialog_content = "<color=#e8d9bb>El gatito mecánico recargado se acicaló con deleite sobre la mesa y golpeó la mano de Connolly con la cabeza.</color>",
  ui_story_2003_4_14_dialog_content = "Acerca del dinero...",
  ui_story_2003_4_15_dialog_content = "Shhh... Aunque amo el dinero y los tesoros tanto como un dragón, simplemente no acepto dinero... ¿Qué tal otra taza de café?",
  ui_story_2003_4_16_dialog_content = "¿Ah?",
  ui_story_2003_4_17_dialog_content = "¿Qué tiene de raro? Mi querida, eres nuestra familia.",
  ui_story_2003_4_18_dialog_content = "Siempre eres bienvenida entre nosotros...",
  ui_story_2003_4_19_dialog_content = "Sheol, Dayna, Robyn, y...",
  ui_story_2003_4_20_dialog_content = "¿Connolly?",
  ui_story_2003_4_21_dialog_content = "Despierta y limpia el café. Café...",
  ui_story_2003_4_22_dialog_content = "¿Es de Dayna? ¿Lo dejó ahí? Dice que...",
  ui_story_2003_4_23_dialog_content = "Otra víctima compró exactamente... Krane... ¡¡El mecánico!!",
  ui_story_2003_4_24_dialog_content = "Quería tanto llegar a Lumopolis... ¡Ahora beberá el extracto! ¿Qué hacemos? ¡Debemos ayudarlo!",
  ui_story_2003_4_25_dialog_content = "No, espera un segundo...",
  ui_story_2003_4_26_dialog_content = "¡Avísanos la próxima vez! ¡Después de todo, somos tu <color=#FFB400>familia</color>!",
  ui_story_2003_4_27_dialog_content = "¿Quieres dejar un mensaje para Dayna?",
  ui_story_2003_4_28_dialog_content = "...Sí. ¡Lo anotaré en la pizarra! “Para Dayna & Robyn, hay una nueva víctima. Las esperaré allá.”",
  ui_story_2003_4_29_dialog_content = "Miau...",
  ui_story_2003_4_30_dialog_content = "¿Conoces el lugar, cierto?",
  ui_story_2003_4_31_dialog_content = "Miau... miau...",
  ui_story_2003_4_32_dialog_content = "¡Vamos juntos!",
  ui_story_2003_4_X1_dialog_content = "Bébelo... Bebe...",
  ui_story_2003_4_X2_dialog_content = "...Lo deseo... mucho...",
  ui_story_2003_4_X3_dialog_content = "Bébelo y te volverás más fuerte, más sabroso también...",
  ui_story_2003_4_X4_dialog_content = "Puedo entender tu duda, así que tómate tu tiempo... Recuerda, encontrarás el camino correcto eventualmente.",
  ui_story_2003_4_33_dialog_content = "Dretchers por todas partes... Ah, son tan difíciles de ver en la oscuridad... No muy peligrosos, pero una gran molestia.",
  ui_story_2003_4_34_dialog_content = "Aquí también está muy oscuro. Esta parece ser su casa. ¿Llegamos a tiempo...?",
  ui_story_2003_4_35_dialog_content = "¿H-hay alguien aquí?",
  ui_story_2003_4_36_dialog_content = "¿No hablé lo suficiente fuerte? ¿H-HAY ALGUIEN AQUÍ?",
  ui_story_2003_4_37_dialog_content = "Miau...",
  ui_story_2003_4_38_dialog_content = "¡Wow, incluso abre la puerta! Es lo suficientemente listo para ser miembro de nuestra Banda de Escala, ¡ja! Solo llámalo Anton Re-menor...",
  ui_story_2003_4_39_dialog_content = "Calla; todavía no sabemos qué está pasando.",
  ui_story_2003_4_40_dialog_content = "La puerta está cerrada...",
  ui_story_2003_4_41_dialog_content = "¡Oh! ¿Está bien Señor Mecánico?",
  ui_story_2003_4_42_dialog_content = "Miau... miau...",
  ui_story_2003_4_43_dialog_content = "¡Ustedes de nuevo! La niña entrometida...y ésta basura. ¿Qué hacen aquí?",
  ui_story_2003_4_44_dialog_content = "Pero, no importa.",
  ui_story_2003_4_X44_dialog_content = "Ya sé cómo llegar a Lumopolis.",
  ui_story_2003_5_1_dialog_content = "<color=#e8d9bb>El frasco vacío yacía inclinado en el suelo, ligeramente agrietado por la caída, con apenas una mancha de líquido de platino en el fondo.</color>",
  ui_story_2003_5_2_dialog_content = "Puedo verlo. Estoy sentado en un dirigible que es arrastrado por el viento y, pisando las nubes, llego a la puerta principal de Lumopolis.",
  ui_story_2003_5_3_dialog_content = "Me reciben ángeles uniformados que hacen sonar sus trompetas para darme la bienvenida, y luego abren las puertas...",
  ui_story_2003_5_4_dialog_content = "También hay un noble, viéndome con una sonrisa en su cara, quien me lleva del brazo y me escolta al palacio.",
  ui_story_2003_5_5_dialog_content = "El olor a comida flota en el aire...",
  ui_story_2003_5_6_dialog_content = "Ahh, esto... esto es...",
  ui_story_2003_5_7_dialog_content = "Ya lo bebió...",
  ui_story_2003_5_8_dialog_content = "Sr. Krane... Señor... ¡¿Puede escucharme?!",
  ui_story_2003_5_9_dialog_content = "¿Es esta... la vida que quiero?",
  ui_story_2003_5_10_dialog_content = "¡Connolly, cuidado!",
  ui_story_2003_5_11_dialog_content = "Gah...",
  ui_story_2003_5_12_dialog_content = "Como dijo Dayna, se ha convertido en cebo para Eclipsites.",
  ui_story_2003_5_13_dialog_content = "Están escondidos en esta habitación... ¡Arghhh! ¡¿Cuántos hay?!",
  ui_story_2003_5_14_dialog_content = "¡Están acechando en la oscuridad, pero no es tiempo para jugar escondidas ahora!",
  ui_story_2003_5_15_dialog_content = "Mantén la calma y no te asustes...",
  ui_story_2003_5_16_dialog_content = "¡Anton! ¡Limpiemos este desastre!",
  ui_story_2003_5_17_dialog_content = "¿Pero por qué me siento tan... vacío?",
  ui_story_2003_5_18_dialog_content = "Esa persona claramente dijo: Bébelo y renacerás, tu sangre impura será purificada, y sangre noble fluirá por tus venas.",
  ui_story_2003_5_19_dialog_content = "Las puertas de Lumopolis ser abrirán ante ti, llevándote no solo al patio, sino también a sus Jardines.",
  ui_story_2003_5_20_dialog_content = "Tocarás la luz del lugar más alto de Lumopolis, y tu alma encontrará su hogar.",
  ui_story_2003_5_21_dialog_content = "¿Pero por qué me siento tan... vacío?",
  ui_story_2003_5_22_dialog_content = "Mi gatito, el que he estado creando y desarrollando toda mi vida con mis conocimientos vitales. ¿Me responderás? ¿Por qué no cantas?",
  ui_story_2003_5_23_dialog_content = "Miau...",
  ui_story_2003_5_24_dialog_content = "¡El último! ¡Listo!",
  ui_story_2003_5_25_dialog_content = "Sr. Krane... Tu... ¡¿Cómo?!",
  ui_story_2003_5_26_dialog_content = "<color=#e8d9bb>Los Dretchers que acechaban en la oscuridad surgieron de repente del caos.</color>",
  ui_story_2003_5_27_dialog_content = "<color=#e8d9bb>Royeron su brazo del mecánico. Sin embargo, ni siquiera se dio cuenta de lo que estaba pasando.</color>",
  ui_story_2003_5_28_dialog_content = "Entre más Dretchers aparecían, él era como un faro brillante que atraía constantemente a los Eclipsites. Y su cuerpo parecía transformarse...",
  ui_story_2003_5_29_dialog_content = "¡Rápido! ¡Aniquilemos a estos malditos Dretchers! ¡Urgh, tan sucios! ¡Ya no puedo más!",
  ui_story_2003_5_30_dialog_content = "Sin dolor, sin frialdad, sin pena... Esta es justo la vida que deseo... Pero...",
  ui_story_2003_5_31_dialog_content = "Por qué...",
  ui_story_2003_5_32_dialog_content = "¡Sr. Krane! Sr. Krane... Si no detenemos esto... Usted va a...",
  ui_story_2003_5_X1_dialog_content = "<color=#FFB400>\"Morir.\"</color>",
  ui_story_2003_5_33_dialog_content = "Si es así... Está bien. No he alcanzado satisfacción al final de todos modos. Finalmente, finalmente...",
  ui_story_2003_5_34_dialog_content = "<color=#e8d9bb>El mecánico levantó ligeramente la cabeza, tan frágil como una hoja de papel, esperando ser engullido por los Eclipsites.</color>",
  ui_story_2003_5_35_dialog_content = "<color=#e8d9bb>El maltrecho gato negro no hizo ningún ruido, simplemente se quedó sentado, observando y asimilando todo.</color>",
  ui_story_2003_6_1_dialog_content = "¿Extrañas Lumopolis, Connolly?",
  ui_story_2003_6_2_dialog_content = "Los altos muros y cúpulas, los edificios blancos iluminados por el resplandor, los soldados que vigilan las murallas... y ningún Eclipsite.",
  ui_story_2003_6_3_dialog_content = "Ese es nuestro hogar también.",
  ui_story_2003_6_4_dialog_content = "¿Qué no es hogar donde está la familia? ¡Soy muy feliz ahora, viviendo con mamá y papá!",
  ui_story_2003_6_5_dialog_content = "Connolly, no entiendes. Esta pequeña casucha no es nuestro hogar real.",
  ui_story_2003_6_6_dialog_content = "Sí... No entiendo. No hay diferencia entre las dos.",
  ui_story_2003_6_7_dialog_content = "Pero estás tan determinada en irte... Con lo que acabé no fue la promesa de volver a Lumopolis, sino...tus obituarios.",
  ui_story_2003_6_8_dialog_content = "Desde entonces he estado sola, pasando la mayor parte de formación entrando y saliendo de casas de familiares, sin un lugar seguro al que acudir.",
  ui_story_2003_6_9_dialog_content = "La magnifica Lumopolis no es mi hogar... Quisiera decirte eso pero... Desearía que me escuches.",
  ui_story_2003_6_10_dialog_content = "(Lamentos indescriptibles)",
  ui_story_2003_6_11_dialog_content = "¿La transformación fue exitosa?",
  ui_story_2003_6_12_dialog_content = "¡¡¡Whoa!!! ¡¿Qué es esto?! ¿De dónde salieron estos Eclipsites? ¿Es este su lugar de desove?",
  ui_story_2003_6_13_dialog_content = "¡Pero el dúo Anton y Connolly es invencible! Juntos podemos...",
  ui_story_2003_6_14_dialog_content = "...",
  ui_story_2003_6_15_dialog_content = "¿Te echas para atrás en silencio?",
  ui_story_2003_6_16_dialog_content = "Desafortunadamente, todos los experimentos previos fallaron. ¿Pero debes sentirte un poco diferente cierto? Después de beber el extracto concentrado.",
  ui_story_2003_6_17_dialog_content = "Transformación... No los Aurorians de Lumopolis, sino las presas de los Eclipsites...",
  ui_story_2003_6_Z17_dialog_content = "Para ser preciso, se trata de volverse más apetitoso. Tu piel y sangre serán transformadas en el catalizador que desean los Eclipsites.",
  ui_story_2003_6_Z18_dialog_content = "Aunque es una pena que las cosas no salieron perfectamente, sería un desperdicio dejárselos a esos bichos descerebrados.",
  ui_story_2003_6_Z19_dialog_content = "Déjame probarlo con cuidado.",
  ui_story_2003_6_Z20_dialog_content = "Eh... ¡¡¡Aaaaaaaaah!!!",
  ui_story_2003_6_18_dialog_content = "¡Sr. Krane!",
  ui_story_2003_6_19_dialog_content = "¡Eclipsites de alto nivel! Tú... ¿Tu hiciste este maldito extracto...?",
  ui_story_2003_6_20_dialog_content = "No, no, no... Eso no es posible. Solo soy un proveedor...ordinario.",
  ui_story_2003_6_21_dialog_content = "Un artefacto tan grandioso y sagrado debe venir de la gloriosa Lumopolis... Solo lo mejoré un poco.",
  ui_story_2003_6_X1_dialog_content = "La felicidad es tan fácil de obtener... Dárselo a los pobres desterrados, conducirlos hacia la paz y la serenidad...",
  ui_story_2003_6_X2_dialog_content = "Y dejarlos convertirse en lo que más anhelan.",
  ui_story_2003_6_X3_dialog_content = "Lumopolis... Cómo...",
  ui_story_2003_6_X4_dialog_content = "Que mal que la transformación aún no está completa. Pero supongo que sabrá bien.",
  ui_story_2003_6_X5_dialog_content = "¿Te importaría no interrumpir mi comida, dulce niña? ¿O quieres transformarte también?",
  ui_story_2003_6_X6_dialog_content = "...Quiero que pares estas atrocidades ahora.",
  ui_story_2003_6_X7_dialog_content = "Me temo que no puedo cumplir tu deseo.",
  ui_story_2003_6_X8_dialog_content = "¡Gahhhhhh!",
  ui_story_2003_6_X9_dialog_content = "¡Tan poderoso! ¡Es difícil de controlar! Es una energía completamente distinta de los otros Eclipsites. Darkflow es tan denso, como si quisiera ahogar a la gente en él.",
  ui_story_2003_6_X10_dialog_content = "Anton...",
  ui_story_2003_6_X11_dialog_content = "¡Aguanta, Connolly!",
  ui_story_2003_6_X12_dialog_content = "Volviste a actuar por tu cuenta, Connolly.",
  ui_story_2003_6_X13_dialog_content = "Pero al menos esta vez lograste progresar y aprendiste a dejarnos mensajes en la pizarra.",
  ui_story_2003_6_X14_dialog_content = "<color=#FFB400> \"Familia\" </color>.",
  ui_story_2003_6_X15_dialog_content = "¡Dayna, Robyn! Tú...",
  ui_story_2003_6_X16_dialog_content = "Tu siempre tendrás un lugar seguro. Es como cuando vamos al café Holiday a relajarnos y divertirnos.",
  ui_story_2003_6_X17_dialog_content = "¡Sí!",
  ui_story_2003_6_X18_dialog_content = "Oye tú, Eclipsite.",
  ui_story_2003_6_X19_dialog_content = "Has estado vendiendo bienes prohibidos y atacando miembros del gremio... ¿Qué tal los honorarios por el tiempo que has estado huyendo, eh?\nSaldaremos nuestras cuentas contigo una por una hoy.",
  ui_story_2003_6_22_dialog_content = "Se acabó...",
  ui_story_2003_6_23_dialog_content = "Sí... Phew...",
  ui_story_2003_6_24_dialog_content = "El gatito...",
  ui_story_2003_6_25_dialog_content = "...Pluto...",
  ui_story_2003_6_26_dialog_content = "Miau, miau...",
  ui_story_2003_6_27_dialog_content = "Dame más tiempo.",
  ui_story_2003_6_28_dialog_content = "*Comienza a tararear*",
  ui_story_2003_6_29_dialog_content = "Es <color=#FFB400>—Hogar—</color>.",
  ui_story_2003_6_30_dialog_content = "¿La canción que tu mamá te enseñó?",
  ui_story_2003_6_31_dialog_content = "Sí, estábamos en Umbraton en ese entonces, y éramos pobres. Incluso aunque éramos Nobles, nuestras vidas se volvieron peor que la de muchos plebeyos.",
  ui_story_2003_6_32_dialog_content = "Aunque, era muy feliz, porque mamá y papá estaban ahí... Pero entonces...",
  ui_story_2003_6_33_dialog_content = "¿Cómo puede ser? Definitivamente puedes cantar...",
  ui_story_2003_6_34_dialog_content = "Podría ser que te niegas a cantarle a esas personas porque... ¿Solo quieres cantarme esa canción a mí?",
  ui_story_2003_6_35_dialog_content = "¿En serio? Siento que... mi vacío se ha llenado...",
  ui_story_2003_6_36_dialog_content = "¡Mi!",
  ui_story_2003_6_37_dialog_content = "...Vete de aquí. Está colapsando.",
  ui_story_2003_6_38_dialog_content = "Tampoco estoy seguro... pero dijo que es de Lumopolis.",
  ui_story_2003_6_39_dialog_content = "En realidad es de Lumopolis...",
  ui_story_2003_6_40_dialog_content = "¿Puedes pararte? Vamos juntos...",
  ui_story_2003_6_41_dialog_content = "No queda tiempo... Por favor, si puedes, dale un hogar.",
  ui_story_2003_6_42_dialog_content = "Hogar... Colapsado...",
  ui_story_2003_6_X42_dialog_content = "Dayna, Robyn... Yo... Quiero decir algo.",
  ui_story_2003_6_43_dialog_content = "Recuerdo Lumopolis como un lugar con fuentes, flores y sol artificial... Un lugar que llaman un paraíso.",
  ui_story_2003_6_44_dialog_content = "Pero me he dado cuenta que no son las cosas superficiales lo que hace felices a las personas.",
  ui_story_2003_6_45_dialog_content = "Cuando estaba en mi punto más bajo, no eran los jardines ni los nobles quienes me salvaron. Fue el jefe, Sr, Istvan, y ustedes.",
  ui_story_2003_6_46_dialog_content = "Gracias... ¡Volvamos al café y tomemos un cappuccino!",
  ui_story_2003_6_47_dialog_content = "<color=#e8d9bb>El pequeño café no ganaba dinero y estaba muy expuesto a peligrosas amenazas, pero se convirtió en el nuevo hogar del gatito.</color>",
  ui_story_2003_6_48_dialog_content = "Dayna, deja de martillarlo, lo arruinarás.",
  ui_story_2003_6_49_dialog_content = "Oye, ¡intento arreglarlo!",
  ui_story_2003_6_50_dialog_content = "*Silenciosamente saca un arma*",
  ui_story_2003_6_51_dialog_content = "¡¡Miau...!!",
  ui_story_2003_6_52_dialog_content = "¿Oye, por qué está corriendo?",
  ui_story_2003_6_53_dialog_content = "No esperaba que las creaciones mecánicas mostraran un deseo de supervivencia tan fuerte y que tuvieran tanta fuerza en un momento de vida o muerte.",
  ui_story_2003_6_54_dialog_content = "Bueno, iba a enseñarte mis nuevas habilidades de reparación. ¿Ah? ¿Dónde está mi Café?\nRecuerdo que no lo toqué...",
  ui_story_2003_6_55_dialog_content = "*Bebiendo el café*",
  ui_story_2003_6_56_dialog_content = "Está bien. Te traeré uno fresco.",
  ui_story_2003_6_57_dialog_content = "Mmmm... Cosa extraña. ¿Los fantasmas acechan en pleno día?",
  ui_story_2003_6_58_dialog_content = "Preferiría no decirle a Dayna que Anton se tomó el café.",
  ui_story_2003_6_59_dialog_content = "<color=#e8d9bb>En cuanto a Connolly, también sería lo mismo.</color>",
  ui_story_2004_1_1_dialog_content = "Veo que el hielo y la nieve nunca se derriten, sin importar la temporada.",
  ui_story_2004_1_2_dialog_content = "Como una barrera, mantiene al enemigo fuera, pero también bloquea mi camino.",
  ui_story_2004_1_3_dialog_content = "Atrapado en una trampa de mi propia creación, mi responsabilidad forja las cadenas de mi propia atadura.",
  ui_story_2004_1_4_dialog_content = "Por tanto tiempo, es suficiente para congelar un corazón abrasador.",
  ui_story_2004_1_5_dialog_content = "<color=#FFB400>Soy la Reina de Northland, pero también una prisionera de Northland.</color>",
  ui_story_2004_1_6_dialog_content = "¡Esto es malo! ¡Muy malo!",
  ui_story_2004_1_7_dialog_content = "¡Izquierda!",
  ui_story_2004_1_8_dialog_content = "¡Exacto!",
  ui_story_2004_1_9_dialog_content = "Los Eclipsites son muy feroces esta vez.",
  ui_story_2004_1_10_dialog_content = "¡Mira mi gran hombre de nieve! ¡No dejen a ninguno pasar!",
  ui_story_2004_1_11_dialog_content = "¡Noah, mira al de en medio! Parece estar llamando refuerzos.",
  ui_story_2004_1_12_dialog_content = "¡¡¡Woogagagagaga!!!",
  ui_story_2004_1_13_dialog_content = "Parece que ha invocado—",
  ui_story_2004_1_14_dialog_content = "Es muy grande...",
  ui_story_2004_1_15_dialog_content = "Es muy grande...",
  ui_story_2004_1_16_dialog_content = "Es tan grande como seis Louises.",
  ui_story_2004_1_17_dialog_content = "¿Todos los Eclipsites pueden crecer tanto? Es fantástico...",
  ui_story_2004_1_18_dialog_content = "Caray, no creí que nada podría superar a mi hombre de nieve en tamaño. Nunca viviré esto.",
  ui_story_2004_1_19_dialog_content = "¡Ah! Es una ataque—",
  ui_story_2004_1_20_dialog_content = "No hay tiempo de relajarse.",
  ui_story_2004_1_21_dialog_content = "¡Es como un mar infinito de Eclipsites!",
  ui_story_2004_1_22_dialog_content = "¡Ayuda! ¡Necesitamos apoyo! ¡Necesitamos apoyo!",
  ui_story_2004_1_23_dialog_content = "¡Solicitando apoyo—!",
  ui_story_2004_1_24_dialog_content = "Shh... Louise, Noah, cállense.",
  ui_story_2004_1_25_dialog_content = "Van a despertar a mi hermana.",
  ui_story_2004_1_26_dialog_content = "¡Nikinis!",
  ui_story_2004_1_27_dialog_content = "¡Y su Majestad!",
  ui_story_2004_1_28_dialog_content = "Al igual que la marea, la ola de Eclipsites retrocederá.",
  ui_story_2004_1_29_dialog_content = "Retrocedan, están condenados a ser enterrados por el hielo y la nieve, sin dejar rastro alguno.",
  ui_story_2004_1_30_dialog_content = "Todos están... congelados.",
  ui_story_2004_1_31_dialog_content = "¡Cómo carámbanos que brotan del suelo!",
  ui_story_2004_1_32_dialog_content = "Cada vez que veo a Su Majestad demostrar su verdadera fuerza, mi corazón se llena de admiración.",
  ui_story_2004_1_33_dialog_content = "Los carámbanos se han roto y han desaparecido sin dejar rastro...",
  ui_story_2004_1_34_dialog_content = "¡Cómo agua evaporándose en el aire, no queda nada!",
  ui_story_2004_1_35_dialog_content = "Este es el milagro de Northland.",
  ui_story_2004_1_36_dialog_content = "El resto de los Eclipsites se están retirando. Aunque no tengan mente, saben lo que es el miedo.",
  ui_story_2004_1_37_dialog_content = "Oigan, Eclipsites—",
  ui_story_2004_1_38_dialog_content = "¡No se atrevan a regresar!",
  ui_story_2004_1_39_dialog_content = "¡Derecha! Las peleas realmente me sacan de quicio—",
  ui_story_2004_1_40_dialog_content = "¡Ni se les ocurra volver!",
  ui_story_2004_1_41_dialog_content = "Por alguna razón, los bandidos pareces ser más activos de lo usual y se han atrevido a cruzar la frontera de Northland.",
  ui_story_2004_1_42_dialog_content = "Su Majestad...",
  ui_story_2004_1_43_dialog_content = "Hermana se ve preocupada, también.",
  ui_story_2004_1_44_dialog_content = "Las sombras se agitan. Este es el momento en que las estrellas se entrelazan.",
  ui_story_2004_1_45_dialog_content = "¡Un minuto, el líder no está muerto!",
  ui_story_2004_1_46_dialog_content = "Su Majestad, ¿lo alcanzamos y lo golpeamos una vez más?",
  ui_story_2004_1_47_dialog_content = "Eso no será necesario—",
  ui_story_2004_1_48_dialog_content = "Mientras no cruce la frontera de Northland. Mi hielo y nieve solo protegen a mi gente.",
  ui_story_2004_1_49_dialog_content = "<color=#e8d9bb>Belén extendió la mano, y un copo de nieve cayó suavemente, tocando su palma pero sin derretirse.</color>",
  ui_story_2004_1_50_dialog_content = "¡Está nevando!",
  ui_story_2004_1_51_dialog_content = "Bueno, en Northland nieva todo el año.",
  ui_story_2004_1_52_dialog_content = "El suelo está cubierto por una alfombra de nieve de nuevo, como algodón, suave y blanca...",
  ui_story_2004_1_53_dialog_content = "¿De quién harás un muñeco de nieve esta vez? ¡Qué hacer a Louise!",
  ui_story_2004_1_54_dialog_content = "¡Está bien!",
  ui_story_2004_1_55_dialog_content = "¡Oye, espera un segundo!",
  ui_story_2004_1_56_dialog_content = "¿Estás loco? ¡Louise no es tan pequeña!",
  ui_story_2004_1_57_dialog_content = "<color=#e8d9bb>Bajo la Aurora, este mundo cubierto de nieve quedó en silencio, y los ecos desvanecidos del combate fueron tragados por el aire helado.</color>",
  ui_story_2004_1_58_dialog_content = "¿Copos de nieve? \"La nieve desciende con mensajeros de lo alto\"...",
  ui_story_2004_1_59_dialog_content = "Nikinis.",
  ui_story_2004_1_60_dialog_content = "Su Majestad.",
  ui_story_2004_1_61_dialog_content = "Prepárese para la bienvenida—",
  ui_story_2004_1_62_dialog_content = "Un <color=#FFB400>visitante de otra tierra</color> está por llegar.",
  ui_story_2004_2_1_dialog_content = "Carleen, no seas grosera. Tu representas la imagen de Lumopolis.",
  ui_story_2004_2_2_dialog_content = "Sí, mi señor. Entiendo.",
  ui_story_2004_2_3_dialog_content = "Ve.",
  ui_story_2004_2_4_dialog_content = "Su alteza Carleen, a una edad temprana, tiene que aventurarse al reino lejano de Northland...",
  ui_story_2004_2_5_dialog_content = "Los Eclipsites están ascendiendo. Con la situación en una coyuntura tan crítica, esta es una opción necesaria.",
  ui_story_2004_2_6_dialog_content = "Tarde o temprano, ella cargará todo el peso de Lumopolis, y será responsable por las vidas de la gente en Lumopolis.",
  ui_story_2004_2_7_dialog_content = "Todo esto es necesario.",
  ui_story_2004_2_8_dialog_content = "Carleen...",
  ui_story_2004_2_9_dialog_content = "*Respira profundo*",
  ui_story_2004_2_10_dialog_content = "Uff.",
  ui_story_2004_2_11_dialog_content = "*Tomando un respiro profundo*",
  ui_story_2004_2_12_dialog_content = "¿Estás nerviosa?",
  ui_story_2004_2_13_dialog_content = "¡Aaaah!",
  ui_story_2004_2_14_dialog_content = "Lo-lo siento. ¡Fue grosero de mi parte!",
  ui_story_2004_2_15_dialog_content = "¿Asustada?",
  ui_story_2004_2_16_dialog_content = "Sí, tengo un poco de miedo... También es mi primera vez en Northland.",
  ui_story_2004_2_17_dialog_content = "Mamá dijo que Northland está cubierto de hielo y nieve, un romántico pero frío \"Reino de Hielo.\"",
  ui_story_2004_2_18_dialog_content = "La luz de las luciérnagas guía a las almas al bosque del sueño eterno, y el narciso blanco lamenta su destino junto al lago...",
  ui_story_2004_2_19_dialog_content = "Cuando estaba en Lumopolis, rara vez vi nieve.",
  ui_story_2004_2_20_dialog_content = "Nunca he visto un reino tan congelado. Es hermoso.",
  ui_story_2004_2_21_dialog_content = "Pero realmente llegar aquí, aún me siento algo nerviosa.",
  ui_story_2004_2_22_dialog_content = "*Tira de la cara de Carleen*",
  ui_story_2004_2_23_dialog_content = "¡Ah! Es esta... ¿Etiqueta de Northland?",
  ui_story_2004_2_24_dialog_content = "¡Jeje! No, es solo que eres muy linda y no puedo evitarlo.",
  ui_story_2004_2_25_dialog_content = "No te preocupes. Como invitada de honor en Northland, todos aquí seguro te tratarán amablemente.",
  ui_story_2004_2_26_dialog_content = "La Reina del Norte. ¿Cómo es ella?",
  ui_story_2004_2_27_dialog_content = "Su Majestad...",
  ui_story_2004_2_28_dialog_content = "¿Digna? ¿Majestuosa? ¿Amable?",
  ui_story_2004_2_29_dialog_content = "Es difícil describirla. Mis palabras son tan estériles como las frías llanuras—",
  ui_story_2004_2_30_dialog_content = "¡Ah, aquí estamos! ¡Cómo sea, lo sabrás cunado la veas!",
  ui_story_2004_2_31_dialog_content = "Bienvenida al trono eterno de Northland—",
  ui_story_2004_2_32_dialog_content = "<color=#FFB400>Palacio de Invierno</color>.",
  ui_story_2004_2_33_dialog_content = "(Qué gran palacio... Incluso parece más magnífico que Lumopolis.)",
  ui_story_2004_2_34_dialog_content = "(¿Todo aquí está hecho con cristales de hielo...?)",
  ui_story_2004_2_35_dialog_content = "(Lo delicados o intrincados que son, y no se derriten.)",
  ui_story_2004_2_36_dialog_content = "Pequeña invitada de lejos, mira aquí.",
  ui_story_2004_2_37_dialog_content = "¡Ah!",
  ui_story_2004_2_38_dialog_content = "Su. Su Majestad... Buen día.",
  ui_story_2004_2_39_dialog_content = "...",
  ui_story_2004_2_40_dialog_content = "Carleen de Lumopolis... Mis mejores deseos están contigo.",
  ui_story_2004_2_41_dialog_content = "Que la amistad entre nuestros dos países dure para siempre, hasta que la Aurora se apague.",
  ui_story_2004_2_42_dialog_content = "...",
  ui_story_2004_2_43_dialog_content = "(¿Por qué no habla Su Majestad? ¿Dije algo mal?)",
  ui_story_2004_2_44_dialog_content = "<color=#e8d9bb>Belén se levantó del trono y pasó por delante de Carleen como si no la hubiera visto. La incómoda vergüenza congeló el aire.</color>",
  ui_story_2004_2_45_dialog_content = "(¿En verdad hice algo malo...?)",
  ui_story_2004_2_46_dialog_content = "¿Pequeña invitada?",
  ui_story_2004_2_47_dialog_content = "¿Ah?",
  ui_story_2004_2_48_dialog_content = "Ven rápido. Su Majestad está esperándote afuera de esta puerta.",
  ui_story_2004_2_49_dialog_content = "¡Ah! ¡Bien!",
  ui_story_2004_2_X1_dialog_content = "(¡Ah, Es ella! ¡Es su Majestad!)",
  ui_story_2004_2_X2_dialog_content = "(No, no estés nerviosa. Cálmate Carleen. Estará bien.)",
  ui_story_2004_2_X3_dialog_content = "(Tal como practicaste antes...)",
  ui_story_2004_2_X4_dialog_content = "S-su Majestad, nosotros...",
  ui_story_2004_2_50_dialog_content = "Schwartz los mandó aquí para aprender como blandir una espada.",
  ui_story_2004_2_51_dialog_content = "Siendo ese el caso, comencemos.",
  ui_story_2004_2_X5_dialog_content = "¿Ah?",
  ui_story_2004_2_52_dialog_content = "¿¡E-Eclipsites!? Cómo puede esto...",
  ui_story_2004_2_X52_dialog_content = "Y ha invocado a otros aliados...",
  ui_story_2004_2_53_dialog_content = "No te preocupes. Es la magia de la Reina—un espejismo de hielo y nieve. Solo haz lo mejor.",
  ui_story_2004_2_54_dialog_content = "¡Gahhhh!",
  ui_story_2004_2_X6_dialog_content = "¿Ganamos?",
  ui_story_2004_2_X7_dialog_content = "Disminuir la vigilancia ahora sólo conducirá a la derrota.",
  ui_story_2004_2_X8_dialog_content = "¿¡Eh!?",
  ui_story_2004_2_55_dialog_content = "Oww... Ay...",
  ui_story_2004_2_56_dialog_content = "¿Eso es todo lo que tienes?",
  ui_story_2004_2_57_dialog_content = "Lo siento, Su Majestad.",
  ui_story_2004_2_X9_dialog_content = "Esos movimientos descoordinados, la dispersión y la confusión tras obtener una ventaja fugaz.",
  ui_story_2004_2_58_dialog_content = "Y de hecho... ni siquiera puedes romper la escarcha en su superficie.",
  ui_story_2004_2_59_dialog_content = "Si te enfrentaras a un Eclipsite real, tu vida habría terminado ahora.",
  ui_story_2004_2_60_dialog_content = "Yo... Lo siento...",
  ui_story_2004_2_X60_dialog_content = "Retira esas palabras inútiles.",
  ui_story_2004_2_61_dialog_content = "Eres débil... El viento y la nieve de Northland devorarán a tu especia en un instante.",
  ui_story_2004_2_62_dialog_content = "Si no puedes pasar esta prueba, quizá Lumopolis sea realmente un clima más adecuado para ti.",
  ui_story_2004_2_63_dialog_content = "Madre, Northland es realmente una tierra congelada.",
  ui_story_2004_2_64_dialog_content = "Es como un pollito, temblando en el viento frío...",
  ui_story_2004_2_65_dialog_content = "Hermana ya no puede más...",
  ui_story_2004_2_66_dialog_content = "Porque sólo así perdurará el brillo de Lumopolis.",
  ui_story_2004_2_67_dialog_content = "Incluso enviarían a una pequeña niña como esta en tal misión. Eso es realmente lo que harían los nobles hipócritas de Lumopolis.",
  ui_story_2004_3_1_dialog_content = "*Arregla los documentos en el escritorio*",
  ui_story_2004_3_2_dialog_content = "Los Eclipsites se mueven a Northland como una marea oscura.",
  ui_story_2004_3_3_dialog_content = "He visto esto pasar muchas veces. Es muy peligroso.",
  ui_story_2004_3_4_dialog_content = "El viento y la nieve teñidas de sangre, la oscuridad royendo la luz...",
  ui_story_2004_3_5_dialog_content = "He visto la noche interminable, como la última candela apagarse.",
  ui_story_2004_3_6_dialog_content = "Pero la Aurora aún brilla tenue en la noche...",
  ui_story_2004_3_7_dialog_content = "Aunque está titilando.",
  ui_story_2004_3_8_dialog_content = "Estoy muy cansada para seguir pensando... Quizás debería tomar una taza de té.",
  ui_story_2004_3_9_dialog_content = "¡Ah-Ja!",
  ui_story_2004_3_10_dialog_content = "Hermana... Estoy nerviosa... ¿Y si los Eclipsites la golpean de nuevo?",
  ui_story_2004_3_11_dialog_content = "Ay... Mi sudor se ha congelado... y mi mano está pegada a mi arma...",
  ui_story_2004_3_X1_dialog_content = "Sigue adelante... No llores.",
  ui_story_2004_3_X2_dialog_content = "Una vez más...",
  ui_story_2004_3_12_dialog_content = "Entonces, ¿qué miras, Nikinis?",
  ui_story_2004_3_13_dialog_content = "Buen día, Su Majestad. Veo a su Majestad, Carleen.",
  ui_story_2004_3_14_dialog_content = "¡Flor de hielo!",
  ui_story_2004_3_15_dialog_content = "Wooga—",
  ui_story_2004_3_16_dialog_content = "(Tranquila... Mantén la calma.)",
  ui_story_2004_3_X3_dialog_content = "(Altura... ¡Esa es mi ventaja! Puedo atacar su parte inferior...)",
  ui_story_2004_3_17_dialog_content = "(¡Y entender su debilidad es también una ventaja importante! Su debilidad...)",
  ui_story_2004_3_18_dialog_content = "¡¡¡Aquí está!!!",
  ui_story_2004_3_19_dialog_content = "¡Gaah!",
  ui_story_2004_3_20_dialog_content = "Falló... otra vez... Hielo...",
  ui_story_2004_3_21_dialog_content = "(Derrota a sus aliados antes de derrotarlo...)",
  ui_story_2004_3_22_dialog_content = "(Pero sigue llamando más aliados. Es como un muro de hierro impenetrable sin una sola forma de atravesarlo.)",
  ui_story_2004_3_23_dialog_content = "¡No puedo rendirme!",
  ui_story_2004_3_24_dialog_content = "Esta herida duele, y... mis pies se congelan también. Están absolutamente congelados.",
  ui_story_2004_3_25_dialog_content = "Pero no puedo rendirme... Vamos—",
  ui_story_2004_3_26_dialog_content = "¡Ahh!",
  ui_story_2004_3_27_dialog_content = "¿Wooga?",
  ui_story_2004_3_28_dialog_content = "Ah, se cayó—aun solo es una niña.",
  ui_story_2004_3_29_dialog_content = "Duele...",
  ui_story_2004_3_30_dialog_content = "No es esa Lady Nikinis y...",
  ui_story_2004_3_31_dialog_content = "¡Su Majestad!",
  ui_story_2004_3_32_dialog_content = "*Mira a un lado en silencio*",
  ui_story_2004_3_33_dialog_content = "(¡Ups! ¡Soy un desastre!)",
  ui_story_2004_3_34_dialog_content = "(Cubierta en nieve, pelo desordenado, y vestido lodoso...)",
  ui_story_2004_3_35_dialog_content = "(¿¡Qué haré!?)",
  ui_story_2004_3_36_dialog_content = "Parece preocuparse por su apariencia. ¡Es tan tierna, como un pequeño muñeco de nieve!",
  ui_story_2004_3_X4_dialog_content = "...",
  ui_story_2004_3_37_dialog_content = "(Haz una reverencia, tal vez primero.)",
  ui_story_2004_3_38_dialog_content = "Que el hielo y la nieve te bendigan. Buen día, Su Majestad, Lady Nikinis.",
  ui_story_2004_3_39_dialog_content = "Buen día, Joven Carleen. Sigue como estabas.",
  ui_story_2004_3_40_dialog_content = "¡Cierto, okey!",
  ui_story_2004_3_41_dialog_content = "¡Haré lo mejor que pueda para vencerlo y completar esta prueba, Su Majestad!",
  ui_story_2004_3_42_dialog_content = "Su Majestad, si pudiera consolar a Su Alteza Carleen, estaría encantada.",
  ui_story_2004_3_43_dialog_content = "Desde ese día, ha venido todos los días a este desafío.",
  ui_story_2004_3_44_dialog_content = "La derriban, luego se levanta de nuevo... La derriban—",
  ui_story_2004_3_45_dialog_content = "Luego se levanta de nuevo...",
  ui_story_2004_3_46_dialog_content = "Después de todo, es una niña que carece de técnica—pero ha progresado mucho.",
  ui_story_2004_3_47_dialog_content = "...",
  ui_story_2004_3_48_dialog_content = "Hermana piensa eso también.",
  ui_story_2004_3_49_dialog_content = "¿Consolarla? No es necesario.",
  ui_story_2004_3_50_dialog_content = "Su Majestad... Se ha ido.",
  ui_story_2004_4_1_dialog_content = "¿Un sueño? Un recuerdo tan lejano...",
  ui_story_2004_4_2_dialog_content = "Shaya.",
  ui_story_2004_4_3_dialog_content = "Esa voz.",
  ui_story_2004_4_4_dialog_content = "Shaya.",
  ui_story_2004_4_5_dialog_content = "¿Es una pesadilla?",
  ui_story_2004_4_6_dialog_content = "Los Eclipsites se acercan. Si siguen llegando, Northland estará completamente perdido.",
  ui_story_2004_4_7_dialog_content = "Pero la Aurora nos ha dado una oportunidad de sobrevivir: el poder del hielo y la nieve.",
  ui_story_2004_4_8_dialog_content = "<color=#e8d9bb>En la palma de la mano de la mujer titilaron cristales de hielo blanco, fríos hasta los huesos, arremolinados con el aura de días pasados.</color>",
  ui_story_2004_4_9_dialog_content = "La frialdad y el frío se condensaron en el frágil cristal de hielo, ocultando su verdadera fuerza.",
  ui_story_2004_4_X1_dialog_content = "Una vez liberado, destruirá todo y derrotará a todos los que se atrevan a invadir este lugar.",
  ui_story_2004_4_X2_dialog_content = "Aun así, el precio también es colosal...",
  ui_story_2004_4_10_dialog_content = "<color=#FFB400>Me temo que nunca saldrás de Northland</color>",
  ui_story_2004_4_X3_dialog_content = "Esta espada de doble filo es muy afilada. Cuando derrotes a tu enemigo, deja cicatrices incurables en tu cuerpo y mente.",
  ui_story_2004_4_11_dialog_content = "El tiempo no graba su marca en tu rostro, pero te lo quita todo.",
  ui_story_2004_4_12_dialog_content = "Acompañado sólo por nieve, debes enfrentarte al mundo solo.",
  ui_story_2004_4_13_dialog_content = "Gah... Gah...",
  ui_story_2004_4_14_dialog_content = "Están aquí.",
  ui_story_2004_4_15_dialog_content = "Ya lo sabía—",
  ui_story_2004_4_16_dialog_content = "El gobierno y el poder no son sólo un medio de control, también significan una misión importante y una gran dificultad.",
  ui_story_2004_4_17_dialog_content = "Incluso si una avalancha golpea, uno debe pararse en su camino, defendiendo a la gente detrás.",
  ui_story_2004_4_18_dialog_content = "Me ofrecí para entrar en esta prisión y nunca me he acobardado ante la adversidad.",
  ui_story_2004_4_19_dialog_content = "¿Qué escogerías?",
  ui_story_2004_4_20_dialog_content = "Yo tomaría el cetro.",
  ui_story_2004_4_21_dialog_content = "Tomaría el control del hielo y la nieve, y vigilaría Northland.",
  ui_story_2004_4_22_dialog_content = "Pero una prisión sigue siendo una prisión.",
  ui_story_2004_4_23_dialog_content = "<color=#e8d9bb>Uno, dos, innumerables Eclipsites. Bethlehem se enfrentó sola a ellos en un combate interminable.</color>",
  ui_story_2004_4_24_dialog_content = "<color=#e8d9bb>Finalmente, derrotó a todos sus enemigos y avanzó, sólo para encontrar a la joven Carleen de pie.</color>",
  ui_story_2004_4_25_dialog_content = "No solo es un sueño, sino también su sueño...",
  ui_story_2004_4_26_dialog_content = "Aurora y Fósforo, oigan mi súplica. Quiero...",
  ui_story_2004_4_27_dialog_content = "Carleen, ¿qué haces?",
  ui_story_2004_4_28_dialog_content = "¡Ah! ¡Su Majestad! Estoy rezando... a la Aurora.",
  ui_story_2004_4_29_dialog_content = "¿Por qué rezaste?",
  ui_story_2004_4_30_dialog_content = "Recé por...",
  ui_story_2004_4_31_dialog_content = "Su Majestad, Si no lo mantengo secreto, ¿se hará realidad?",
  ui_story_2004_4_32_dialog_content = "Es más seguro guardar los secretos en el corazón, pero prefiero presentárselos a la Aurora.",
  ui_story_2004_4_33_dialog_content = "Porque hago lo que digo. Siempre soy fiel a mi palabra.",
  ui_story_2004_4_34_dialog_content = "Es increíble, Su Majestad...",
  ui_story_2004_4_35_dialog_content = "Luego yo... ¡Déjame decírtelo en secreto!",
  ui_story_2004_4_36_dialog_content = "Mi deseo es... Se fuerte. Ser tan fuerte como usted.",
  ui_story_2004_4_37_dialog_content = "Ser fuerte...",
  ui_story_2004_4_38_dialog_content = "Soy tan débil ahora.",
  ui_story_2004_4_39_dialog_content = "No sé cuando empezó, pero mi vida parece un completo desorden de repente.",
  ui_story_2004_4_40_dialog_content = "Mi madre está enferma, y no la he visto por mucho tiempo.",
  ui_story_2004_4_X4_dialog_content = "Papá frunce el ceño como si nunca fuera a sonreír de nuevo.",
  ui_story_2004_4_X5_dialog_content = "No he escuchado noticias de mi hermana—",
  ui_story_2004_4_X6_dialog_content = "Recuerdo que ella es amable y gentil, pero ahora su rostro se ha vuelto borroso en mi mente.",
  ui_story_2004_4_41_dialog_content = "Incluso la indestructible Lumopolis ha comenzado a romperse.",
  ui_story_2004_4_X7_dialog_content = "Los muros de la ciudad son tan fuertes como nunca, pero se ven tan frágil ahora en mis ojos—",
  ui_story_2004_4_42_dialog_content = "Aunque no hay nada que pueda hacer al respecto.",
  ui_story_2004_4_43_dialog_content = "Si fuera tan poderoso como tú, todo estaría bien.",
  ui_story_2004_4_44_dialog_content = "¿Todo estaría bien? Je...",
  ui_story_2004_4_45_dialog_content = "¿Ah? ¿Se acaba de reír?",
  ui_story_2004_4_46_dialog_content = "Tú... ¿Te ríes de mí?",
  ui_story_2004_4_47_dialog_content = "No, tu pequeña oración es tan preciosa como una estrella, que brilla en la noche.",
  ui_story_2004_4_48_dialog_content = "(¡Es casi como si estuviera alabando!)",
  ui_story_2004_4_49_dialog_content = "¿Por qué rezaría entonces?",
  ui_story_2004_4_50_dialog_content = "Ya es tan poderosa. ¿Hay algo más que pueda desear?",
  ui_story_2004_4_51_dialog_content = "Claro que lo hay.",
  ui_story_2004_4_52_dialog_content = "Claro que hay algo que quiero—",
  ui_story_2004_4_53_dialog_content = "Es lo mismo que tú quieres.",
  ui_story_2004_5_1_dialog_content = "¡Izquierda! ¡A tu izquierda!",
  ui_story_2004_5_2_dialog_content = "¡Whoa! Estuvo cerca. ¡Parece haber una oportunidad!",
  ui_story_2004_5_3_dialog_content = "¡Hielo! ¡Flor—!",
  ui_story_2004_5_4_dialog_content = "¡Increíble! Carleen, ¡eres tan poderosa!",
  ui_story_2004_5_5_dialog_content = "Tu entrenamiento ha dado frutos. Parece que tu deseo de enfrentarte solo al líder de los Eclipsites no era sólo un sueño—",
  ui_story_2004_5_6_dialog_content = "¡¡¡Gaah!!!",
  ui_story_2004_5_7_dialog_content = "¡¡Ay!!",
  ui_story_2004_5_8_dialog_content = "¡Ah! ¡Cayó!",
  ui_story_2004_5_9_dialog_content = "Retira esas palabras.",
  ui_story_2004_5_10_dialog_content = "¡No, no importa! ¡Aun puedo pelear!",
  ui_story_2004_5_11_dialog_content = "¡Lo más importante es comprender plenamente el poder de Lumina y adoptarlo con cuidado!",
  ui_story_2004_5_12_dialog_content = "Al igual que Louise, el poder que la llama es la Luminaria del Bosque.",
  ui_story_2004_5_13_dialog_content = "Usada correctamente, puede hacer estallar una fuerza poderosa.",
  ui_story_2004_5_14_dialog_content = "En cuanto a Carleen...",
  ui_story_2004_5_15_dialog_content = "¡Debería ser Agua! Esa Lumina...",
  ui_story_2004_5_X1_dialog_content = "Como debería explicarlo... ¡Aunque no puedo verla, puedo sentir su sabor a arándanos!",
  ui_story_2004_5_16_dialog_content = "Comprender la Lumina...",
  ui_story_2004_5_17_dialog_content = "¡Derecha! Usa el poder en tu mente para sentirlo. ¡Déjame demostrarte!",
  ui_story_2004_5_18_dialog_content = "Siéntelo... Concéntrate, concéntrate—",
  ui_story_2004_5_19_dialog_content = "Se siente como... el olor a foca asada. Está carbonizado y crujiente, candente y sabroso.",
  ui_story_2004_5_20_dialog_content = "¡Ah! Tengo hambre.",
  ui_story_2004_5_21_dialog_content = "Ahora que lo mencionas, también tengo hambre.",
  ui_story_2004_5_22_dialog_content = "No me mires a mí. No estoy—",
  ui_story_2004_5_23_dialog_content = "Hambrienta...",
  ui_story_2004_5_24_dialog_content = "Tengo hambre, también.",
  ui_story_2004_5_25_dialog_content = "Los niños buenos no saben mentir.",
  ui_story_2004_5_26_dialog_content = "¡Bien, aquí vamos de nuevo, Carleen!",
  ui_story_2004_5_27_dialog_content = "Espera a que lo derrotemos... ¡Iremos a comer algo sabroso!",
  ui_story_2004_5_28_dialog_content = "¡Está bien!",
  ui_story_2004_5_29_dialog_content = "Se ha hecho muy amiga de Noah y Louise.",
  ui_story_2004_5_30_dialog_content = "Ha entrenado todos los días por un mes.",
  ui_story_2004_5_31_dialog_content = "Incluso cuando nevaba mucho, llegaba temprano y practicaba hasta altas horas de la noche. Era una chica tan buena.",
  ui_story_2004_5_32_dialog_content = "Se ve más poderosa que antes. Aunque su habilidad necesita pulirse, ha aprendido como encontrar la debilidad de los Eclipsites.",
  ui_story_2004_5_33_dialog_content = "Esta vez, puede tener éxito.",
  ui_story_2004_5_X33_dialog_content = "Tiene un largo camino por delante, pero...",
  ui_story_2004_5_34_dialog_content = "Esperaremos y veremos.",
  ui_story_2004_5_35_dialog_content = "¿Ah?",
  ui_story_2004_5_36_dialog_content = "¿Estás tan sorprendida? Parece que en tu mente soy un poco dura.",
  ui_story_2004_5_37_dialog_content = "Realmente no me gusta Lumopolis, pero Carleen—",
  ui_story_2004_5_38_dialog_content = "Como dijo, es una buena niña.",
  ui_story_2004_5_39_dialog_content = "¡Golpe final!",
  ui_story_2004_5_40_dialog_content = "¡S-se ha caído!",
  ui_story_2004_5_41_dialog_content = "¡Se ha caído!",
  ui_story_2004_5_42_dialog_content = "Se disipó en copos de nieve, congelados por completo.",
  ui_story_2004_5_43_dialog_content = "Aunque los copos de nieve son diminutos, cada uno es único.",
  ui_story_2004_5_44_dialog_content = "Mira este hexagonal, es como si hubiera sido cortado en rodajas finas. Esto se llama un cristal laminar. Es como una pintura.",
  ui_story_2004_5_45_dialog_content = "Este tipo, con puntas en ambos extremos como agujas, se llama cristal acicular.",
  ui_story_2004_5_46_dialog_content = "Son adorables. Es la primera vez que observo estos copos de nieve con tanta atención desde que llegué aquí.",
  ui_story_2004_5_47_dialog_content = "¡Y los copos que creó Carleen también son hermosos!",
  ui_story_2004_5_X2_dialog_content = "¿D-de veras?",
  ui_story_2004_5_X3_dialog_content = "Los copos de nieve solo pueden nacer en ambientes extremadamente fríos.",
  ui_story_2004_5_X4_dialog_content = "¡Temperaturas tan frías como para congelarte!",
  ui_story_2004_5_X5_dialog_content = "Pero creo que, por unos copos de nieve tan bonitos, ¡merece la pena!",
  ui_story_2004_5_X6_dialog_content = "—y, claro, fui inteligente como para ponerme ropa muy gruesa para mantenerme caliente mientras miro los copos de nieve.",
  ui_story_2004_5_X7_dialog_content = "Ah, Carleen... ¿Tienes frío?",
  ui_story_2004_5_X8_dialog_content = "U-Un poco.",
  ui_story_2004_5_X9_dialog_content = "Si sientes frío, Noah te dará un abrazo. ¿Qué te parece?",
  ui_story_2004_5_X10_dialog_content = "Mmm... Tan tibio.",
  ui_story_2004_5_48_dialog_content = "¡Ah! ¡Su Majestad!",
  ui_story_2004_5_49_dialog_content = "¡Su Majestad! Que el hielo y la nieve te bendigan.",
  ui_story_2004_5_50_dialog_content = "¡H-he derrotado a los Eclipsites y completado su prueba!",
  ui_story_2004_5_51_dialog_content = "Aunque estoy segura que en su opinión, mi rendimiento no es perfecto... Todavía hay mucho margen de mejora.",
  ui_story_2004_5_52_dialog_content = "Y yo... No diría que he trabajado especialmente duro...",
  ui_story_2004_5_53_dialog_content = "¡Solo diré que nunca estaré satisfecha con mi fuerza actual! ¡Seguiré aprendiendo!",
  ui_story_2004_5_54_dialog_content = "¿Por qué te exiges tanto? Aún eres muy joven.",
  ui_story_2004_5_55_dialog_content = "A pesar de haberte hecho pasar una prueba tan difícil, habría estado bien escapar. Nadie hubiera pensado menos de ti.",
  ui_story_2004_5_56_dialog_content = "Ni siquiera tu padre habría dicho algo.",
  ui_story_2004_5_57_dialog_content = "...todo fue por Lumopolis. Quiero defender nuestro hogar—el lugar donde mi gente vivía feliz.",
  ui_story_2004_5_58_dialog_content = "Así que viniste a Northland sola, sin miedo en tu corazón.",
  ui_story_2004_5_59_dialog_content = "Sí.",
  ui_story_2004_5_X11_dialog_content = "Carleen...",
  ui_story_2004_5_X12_dialog_content = "(Hay un poco de inquietud en sus ojos, pero aún más determinación.)",
  ui_story_2004_5_X13_dialog_content = "(En cuanto a Joshua, y las responsabilidades que debe asumir, parece, hasta cierto punto, consciente de lo que depara el futuro.)",
  ui_story_2004_5_X14_dialog_content = "(Pero lo que le venga, está preparada para todo.)",
  ui_story_2004_5_60_dialog_content = "Es algo similar a mí. ¿Schwartz lo veía venir, verdad? ¿eh?",
  ui_story_2004_5_61_dialog_content = "Pero está bien.",
  ui_story_2004_5_62_dialog_content = "¿Qué?",
  ui_story_2004_5_63_dialog_content = "Carleen, te has vuelto más fuerte, pero pronto entenderás que—",
  ui_story_2004_5_64_dialog_content = "El precio por gran poder es soledad interminable. Pronto lo sabrás.",
  ui_story_2004_5_65_dialog_content = "Ahora, ve a ponerte algo de ropa de abrigo y descansa bien.",
  ui_story_2004_5_66_dialog_content = "Mañana enfrentarás tu verdadera prueba.",
  ui_story_2004_6_1_dialog_content = "Esta es la frontera de Northland. El hielo y la nieve que se extienden por miles de kilómetros se detienen aquí.",
  ui_story_2004_6_2_dialog_content = "Dentro de estas fronteras se encuentra un frío santuario, pero el mundo exterior es extremadamente peligroso y está lleno de Eclipsites.",
  ui_story_2004_6_3_dialog_content = "Mira. Están viniendo.",
  ui_story_2004_6_4_dialog_content = "Grrrr—",
  ui_story_2004_6_5_dialog_content = "¿Eh? ¡Es el mismo de antes!",
  ui_story_2004_6_6_dialog_content = "Acaba de traer consigo a unos cuantos amiguitos. ¿Quizás nos han subestimado?",
  ui_story_2004_6_7_dialog_content = "No—espera un segundo...",
  ui_story_2004_6_8_dialog_content = "Detrás de él... Hay más de ellos siguiendo...",
  ui_story_2004_6_9_dialog_content = "¡Hay más que siguen en la retaguardia!",
  ui_story_2004_6_10_dialog_content = "Hay demasiados... ¿Están locos estos Eclipsites?",
  ui_story_2004_6_11_dialog_content = "¿Has visto a su líder?",
  ui_story_2004_6_12_dialog_content = "Usan el poder oscuro para convocar a sus secuaces en un intento de corromper la nieve pura.",
  ui_story_2004_6_13_dialog_content = "Carleen, déjame ver lo que has logrado en los últimos días. Derríbalo.",
  ui_story_2004_6_14_dialog_content = "Puedo... ¿Puedo hacerlo?",
  ui_story_2004_6_15_dialog_content = "Aunque quiero volverme más fuerte, realmente...",
  ui_story_2004_6_16_dialog_content = "No tengas miedo. Estás lista para esto.",
  ui_story_2004_6_17_dialog_content = "¿Ah?",
  ui_story_2004_6_19_dialog_content = "El trabajo duro da frutos. Cree en ti misma, en tu credo y aspiración.",
  ui_story_2004_6_20_dialog_content = "¡Ja! ¡El último!",
  ui_story_2004_6_21_dialog_content = "No podemos dejar que escapen esta vez.",
  ui_story_2004_6_22_dialog_content = "¡Yo también me he ocupado de los de aquí!",
  ui_story_2004_6_23_dialog_content = "Al principio parecían un enjambre imparable, pero resultaron ser una especie de broma.",
  ui_story_2004_6_24_dialog_content = "Bueno, quién sabe cuándo aprenderán la lección, aunque ciertamente no me importa luchar contra ellos.",
  ui_story_2004_6_25_dialog_content = "Me pregunto cómo le va a Carleen...",
  ui_story_2004_6_26_dialog_content = "Ya está oscuro.",
  ui_story_2004_6_27_dialog_content = "(Sentir la fuerza de la Luz, sí-ver la debilidad del enemigo.)",
  ui_story_2004_6_28_dialog_content = "(Ritmo, no estropear el ritmo.)",
  ui_story_2004_6_29_dialog_content = "(Ya no puedo levantar los brazos y se me congela la cara... ¡pero seguro que no me caigo antes!)",
  ui_story_2004_6_30_dialog_content = "(Esto no es nada, ya conozco todos sus trucos. Despacio, ahora... Poco a poco...)",
  ui_story_2004_6_31_dialog_content = "¡El tiempo es ahora!",
  ui_story_2004_6_32_dialog_content = "¡Carleen! Tú... ¡Lo hiciste!",
  ui_story_2004_6_33_dialog_content = "Vencí, a un verdadero Eclipsite, un Eclipsite muy poderoso... Nunca creí que podría.",
  ui_story_2004_6_34_dialog_content = "Hiciste un buen trabajo.",
  ui_story_2004_6_35_dialog_content = "<color=#e8d9bb>Belén se adelantó y tocó suavemente la cabeza de Carleen.</color>",
  ui_story_2004_6_36_dialog_content = "Aunque la Luz es débil ahora, iluminará el cielo entero algún día.",
  ui_story_2004_6_37_dialog_content = "Carleen, mira.",
  ui_story_2004_6_38_dialog_content = "<color=#e8d9bb>El cielo de Northland era tan hermoso, con la bella Aurora flotando por encima, tan brillante como un sueño puro.</color>",
  ui_story_2004_6_39_dialog_content = "Bajo la oscuridad de la noche, casi parece que se puede extender una mano y tocar la Aurora que flota ligeramente.",
  ui_story_2004_6_40_dialog_content = "Es tan hermoso...",
  ui_story_2004_6_41_dialog_content = "Northland es un lugar tan hermoso, digno de arriesgar la vida de uno para proteger.",
  ui_story_2004_6_42_dialog_content = "¿Y qué hay de Lumopolis? ¿Qué clase de lugar es Lumopolis para ti?",
  ui_story_2004_6_43_dialog_content = "Lumopolis descansa en lo alto del cielo, derramando su luz desde lo alto.",
  ui_story_2004_6_44_dialog_content = "Padre, Madre, los Ángeles, y toda la gente maravillosa que vive ahí.",
  ui_story_2004_6_45_dialog_content = "En mi corazón, es tan linda como Northland.",
  ui_story_2004_6_46_dialog_content = "¿En serio?",
  ui_story_2004_6_47_dialog_content = "Una vez escuché de mi padre que has estado cuidando esta tierra solo durante mucho tiempo.",
  ui_story_2004_6_48_dialog_content = "¿Es realmente solitario, ser tan fuerte?",
  ui_story_2004_6_49_dialog_content = "Sí lo es. La soledad es amargamente fría—más fría que la escarcha. No obstante, no me arrepiento.",
  ui_story_2004_6_50_dialog_content = "Por este hermoso reino de Northland, y su hermosa Aurora.",
  ui_story_2004_6_51_dialog_content = "¿Puedes entender, cierto?",
  ui_story_2004_6_52_dialog_content = "Entiendo.",
  ui_story_2004_6_X1_dialog_content = "Aunque nadie lo entienda, aunque tenga que soportar grandes sufrimientos, tengo que... ser yo.",
  ui_story_2004_6_X2_dialog_content = "El que lleva el peso del mundo y protege a todos detrás de nosotros.",
  ui_story_2004_6_X3_dialog_content = "Aún si estoy sola.",
  ui_story_2004_6_53_dialog_content = "Bien. Carleen, has pasado la prueba.",
  ui_story_2004_6_54_dialog_content = "Ahora, te enseñaré algunas habilidades de combate reales."
}
return config
